update content_bodies set title = '斜めの旅もいいんじゃない？【にし阿波傾斜地農業＊キャンプ・徳島県三好市＆東みよし町】', description = '世界農業遺産の認定地「にし阿波」で、昔ながらの傾斜地での農業を体験！
