【Introduction to Ogaki City】
Located in the western part of Gifu Prefecture, in the center of Nishi-Mino, Ogaki is a city with a population of 160,000, known for its abundant underground water, earning it the nickname ''Water City Ogaki'' since ancient times.
It is known as the ending point of Matsuo Basho''s travelogue ''The Narrow Road to the Deep North'' and features Ogaki Castle, which served as the base for Ishida Mitsunari of the Western Army during the Battle of Sekigahara, as well as the Sumiyaki Castle, said to have been built by Toyotomi Hideyoshi in a single night, making it a city where nature and history coexist.
