update content_bodies set title = '【ライブ】大垣まつり（R4.5.15）', description = '大垣祭の軕行事は、大垣の城下町祭礼として伝承されてきた美濃地方を代表する祭礼行事であり、大垣藩主下賜(かし)の軕と町衆の軕が併存する形態は全国的にも希少です。
　また、からくり人形には中京圏の山車(だし)行事、軕上(やまじょう)の芸能には近畿圏の山車行事の影響が色濃く、東西の祭礼文化の交渉がうかがわれるなど、国内の山・鉾・屋台(やま・ほこ・やたい)行事の伝播や変遷を理解する上で重要であると評価されています。

