[Introduction to Ogaki City]
Located in the western part of Gifu Prefecture, in the center of Nishi-Mino, Ogaki is a city with a population of 160,000, blessed with abundant underground water, and has long been known as "the Water City of Ogaki."
It is known as the ending point of Matsuo Basho''s travelogue "The Narrow Road to the Deep North" and features Ogaki Castle, which served as the base for Ishida Mitsunari of the Western Army during the Battle of Sekigahara, as well as the Sumiyoshi Night Castle, said to have been built by Toyotomi Hideyoshi in a single night. It is a city where nature and history coexist.
From late March to May, the Ogaki Festival, which was registered as a UNESCO Intangible Cultural Heritage in 2016, along with boat rides and tarai boats, attracts many tourists and is bustling with activity.

