update content_bodies set title = '大垣市移住定住プロモーション動画', description = '大垣から、はじめよう。

都会の生活に心奪われていく男性が、大垣市に暮らす恋人の女性との会話のなかで、魅力あふれる現在の大垣市の様子を知り、故郷を思い出すなかで大切なことに気づき、大垣に戻ってくるという動画を制作しました。

ＢＧＭは現代版にアレンジした「木綿のハンカチーフ」。
本来、この曲は、故郷で暮らす女性が、都会に染まって旅立ってしまった恋人の男性のことを思う歌詞ですが、この動画では、故郷で暮らす女性が、大垣の魅力を伝えて、都会に染まりそうになる恋人の男性を故郷に呼び戻してしまうというストーリーとなっております。

出演者：根矢 涼香、森岡 龍

監督：二瓶 剛
撮影監督：古屋 幸一
撮影補：オカザキ タカユキ
監督補：横溝 倫明、岡村 真亜沙
