update content_bodies set title = 'Ogaki City Migration and Settlement Promotion Video', description = 'Let''s start from Ogaki.

A man captivated by city life learns about the charming current state of Ogaki City through conversations with his girlfriend who lives there. As he reminisces about his hometown, he realizes what is truly important and decides to return to Ogaki.

The background music is a modern arrangement of "Cotton Handkerchief." Originally, this song''s lyrics express the feelings of a woman living in her hometown who thinks of her boyfriend who has left for the city. However, in this video, the story is about a woman living in her hometown conveying the charm of Ogaki and calling back her boyfriend, who is about to be influenced by city life.

