update content_bodies set title = '【岐阜県大垣市】ユネスコ無形文化遺産　山・鉾・屋台行事　大垣祭の軕行事', description = '大垣まつりは370年余り続く大垣八幡神社の例大祭です。
毎年5月15日に最も近い土日に開催されます。
十三両の軕（やま）がおよそ8.8kmを練り歩く様子は圧巻。平成27年に国重要無形民俗文化財に指定、平成28年には「大垣祭りの軕行事」がユネスコ無形文化遺産に登録されました。

