update content_bodies set title = 'Untouched Hokkaido : Japan’s Natural Wonderland(Summer)', description = 'Website: http://untouchedhokkaido.jp/
FACEBOOK: https://www.facebook.com/untouchedhokkaido/
Instagram: https://www.instagram.com/untouched_hokkaido/?hl=en

歴史的・地理的に、ユニークな場所である東北海道は、⽇本でありながら北⽶プレートに位置するため、その植⽣はとてもに珍しい種類で溢れている。この⼟地だからこそ出逢える希少な野⽣⽣物、そして多くの⽣き物が暮らす⽇本の国⽴公園はその⾃然と共⽣する地元の⼈々がずっと昔から守りぬいてきた『⾃然が⼿付かずで残る場所（Untouched
Hokkaido）』。 東北海道、この地域は豊かな清流でつながっており、日本の特別天然記念物でもある、優雅で美しいタンチョウが住んでいる。北海道の先住民族であるアイヌの言葉で、タンチョウはサロルンカムイ（湿原に住む神）と呼ばれていた。
水は生命を育みながら、魔法をかけられたようにさまざまなカタチに変化する。' where id = 't0Q1K5AXHwz4oVYze7__R';
update content_bodies set title = 'Untouched Hokkaido : Japan’s Natural Wonderland(Summer)', description = 'Website: http://untouchedhokkaido.jp/
FACEBOOK: https://www.facebook.com/untouchedhokkaido/
Instagram: https://www.instagram.com/untouched_hokkaido/?hl=en

Historically and geographically, Eastern Hokkaido is a unique place that, while being in Japan, is located on the North American Plate, resulting in a rich variety of rare plant species. It is here that you can encounter rare wildlife, and the many creatures that inhabit Japan''s national parks have been preserved by the local people who have coexisted with nature for generations, creating a place where ''nature remains untouched (Untouched Hokkaido)''. Eastern Hokkaido is connected by rich, clear streams, and is home to the elegant and beautiful red-crowned crane, which is also a special natural monument of Japan. In the language of the Ainu, the indigenous people of Hokkaido, the red-crowned crane is called Sarorunkamuy (the god that lives in the marshlands). Water nurtures life while magically transforming into various forms.' where id = 'seggTBqWTGmoS4CGE9IcK';
