update content_bodies set title = '東洋一美しいビーチ ～ Yonaha Maehama Beach the best beach in the orient ～', description = '宮古島の与那覇前浜ビーチは様々なランキングで何度も1位をとったことのある、宮古島が誇る東洋一美しいビーチです。全長約7キロも広がるきめ細やかで真っ白い砂浜、時間ごとに刻々と変化する宮古ブルーのグラデーションを、空撮映像でおたのしみください✨


