update content_bodies set title = 'The Most Beautiful Beach in the Orient - Yonaha Maehama Beach', description = 'Yonaha Maehama Beach in Miyako Island is renowned for being the most beautiful beach in the Orient, having ranked first in various rankings multiple times. Enjoy the fine, pure white sandy beach that stretches approximately 7 kilometers and the ever-changing gradient of Miyako Blue throughout the day in aerial footage. ✨

A digital version of the brochure showcasing the beautiful scenery of the Miyako Islands has been released! 
Please take a look.
https://miyako-guide.actibookone.com/' where id = 'zQ_k0QzKDkEc5X1SLG84S';
update content_bodies set title = '宇和島 ～宇和島を知りたくなる', description = '愛媛県宇和島市のブランドムービーは３種類あります。
　宇和島に興味を持った人が、それぞれの興味の在り処に応じて本市との関わり合いを想像できるように、という想いを込めて制作しました。
　本市の魅力資源のうち、自然や産業、文化資源を中心に紹介する内容になっています。宇和島がどんな町か知りたいと思った方におすすめです。
#宇和島#宇和島市#うわじま#ブランドムービー
