00：48頃～　宇和島の花（法華津峠の菜の花、南楽園の梅、菖蒲）#花#菜の花#梅#菖蒲#南楽園
01：06頃～　遊子水荷浦の段畑　#遊子#水荷浦#段畑
01：16頃～　御槇地区　#御槇#津島町
01：26頃～　海の暮らし（真鯛の出荷・宇和島鯛めしなど）#真鯛#鯛めし
01：43頃～　里の暮らし（三間米・コスモス）　#三間#米#三間米#コスモス
01：53頃～　川の暮らし（岩松川・しらうお漁）　#岩松#岩松川#しらうお漁
02：11頃～　真珠　#真珠#宇和島真珠
02：35頃～　宇和島の祭り（牛鬼まつり・吉田秋祭り）　#牛鬼#牛鬼まつり#吉田#吉田秋祭り
03：02頃～　闘牛　#闘牛#闘牛場
03：11頃～　海と花火大会　#花火#花火#花火大会#海と花火大会' where id = 'JpCFo9LkEJwcQnQDc4_59';
update content_bodies set title = 'Uwajima - Discovering Uwajima', description = 'There are three types of brand movies for Uwajima City, Ehime Prefecture.

They were created with the hope that those interested in Uwajima can imagine their connection to the city based on their individual interests.

The content focuses on introducing the city''s attractive resources, particularly its natural, industrial, and cultural assets. It is recommended for those who want to know what kind of town Uwajima is.
#宇和島#宇和島市#うわじま#ブランドムービー
【Reference】Overview of each chapter
00:00~  Uwajima Castle and Cherry Blossoms  #宇和島城#桜
00:10~  Uwajima Sea  #海#宇和海
00:18~  Citrus Terraced Fields and More  #柑橘#みかん#段々畑
