01:06~  Yusui Mizunagura Terraced Fields  #遊子#水荷浦#段畑
01:16~  Omaki District  #御槇#津島町
01:26~  Life by the Sea (Shipping of Tai, Uwajima Tai Meshi, etc.)  #真鯛#鯛めし
01:43~  Life in the Countryside (Mikama Rice, Cosmos)  #三間#米#三間米#コスモス
01:53~  Life by the River (Iwamatsu River, Shirauo Fishing)  #岩松#岩松川#しらうお漁
02:11~  Pearls  #真珠#宇和島真珠
02:35~  Festivals of Uwajima (Ushioni Festival, Yoshida Autumn Festival)  #牛鬼#牛鬼まつり#吉田#吉田秋祭り
03:02~  Bullfighting  #闘牛#闘牛場
03:11~  Sea and Fireworks Festival  #花火#花火#花火大会#海と花火大会' where id = 'LZcSa2WkcQd9kqNf34kTg';
update content_bodies set title = '海神楽2018　9月15日　石見神楽（30秒版）', description = '島根県の誇る伝統芸能「石見神楽」。
華やかな演出が観光客のみなさんにも人気です。
そんな石見神楽を、幻想的なロケーションで楽しむことができる、島根県大田市温泉津町の「海神楽」。
海岸に設営した舞台で、石見神楽が日本海をバックに迫力満点に上演されます。' where id = 'XJHjOjTvKfHZw3xTP97Z6';
update content_bodies set title = 'Umikagura 2018 September 15 Iwami Kagura (30-second version)', description = 'The traditional performing art ''Iwami Kagura'' that Shimane Prefecture is proud of.
Its glamorous performances are popular among tourists.
You can enjoy Iwami Kagura in a fantastic location at ''Umikagura'' in Yunotsu Town, Oda City, Shimane Prefecture.
Iwami Kagura is performed powerfully against the backdrop of the Sea of Japan on a stage set up on the coast.' where id = 'G_vSuoDi6waPHKseiFCQM';
update content_bodies set title = '宇和島を巡る ～宇和島に行きたくなる／連れていきたくなる', description = '#花火大会 #喫茶店 #真珠
愛媛県宇和島市のブランドムービーは３種類あります。
　宇和島に興味をもっていただいた方が、それぞれの興味の在り処によって、本市との関わり合いをご想像いただけるように、という想いを込めて制作しました。
　単に観光地を紹介するといった方法を採らず、旅行客の視点で見た宇和島ということが感じられるように、主観のカメラワークを多用しながら、宇和島を「暮らすように旅する」形で、産業や文化に関わる人たちの日常場面や風景（＝日常の豊かさ）を紹介しています。３本の動画の中で最もブランドムービーらしい内容となっています。　#宇和島#うわじま#宇和島市#ブランドムービー
【参考】各チャプターの概要
　00：00～　　宇和島駅　#宇和島駅
　00：30頃～　宇和島市中心部全景　#宇和島市全景#全景
　00：38頃～　木屋旅館　#木屋旅館
　01：05頃～　市街地中心部の街歩き（民芸店・旗幟店など）　#民芸#張り子#旗幟
　01：43頃～　祭りを楽しむ（牛鬼まつり・納涼夜市・盆踊り・花火大会）#牛鬼まつり#花火大会
　02：50頃～　大浦荷さばき施設でのセリ　#セリ#魚市場#大浦
　03：08頃～　じゃこ天製造風景　#じゃこ天
　03：32頃～　喫茶店　#喫茶店
　03：44頃～　宇和島城　#宇和島城
　04：16頃～　九島　#九島
　05：21頃～　魚類養殖・真珠養殖の作業風景　#養殖#真珠#ブリ#鯛
　05：55頃～　御槇地区　#御槇#津島町
　06：13頃～　闘牛　#闘牛#闘牛場
　06：50頃～　みかん山の収穫作業風景　#みかん#みかん山
　07：16頃～　宇和島駅' where id = 'DPftyOTSexk-fL8NpmdYg';
update content_bodies set title = 'Exploring Uwajima - A Place You Want to Visit / Take Someone To', description = '#Fireworks Festival #Café #Pearls
The brand movie of Uwajima City, Ehime Prefecture, consists of three types.
It was created with the hope that those who become interested in Uwajima can imagine their connection with the city based on their individual interests.
Rather than simply introducing tourist spots, we have used subjective camera work to convey the experience of Uwajima from the perspective of travelers, showcasing the daily scenes and landscapes related to industries and culture (the richness of everyday life) in a way that allows you to ''travel as if you live here.'' This is the most brand movie-like content among the three videos. #Uwajima #UwaJima #UwajimaCity #BrandMovie
【Reference】Overview of Each Chapter
00:00~ Uwajima Station #UwajimaStation
00:30~ Overview of Uwajima City Center #UwajimaCityOverview #Overview
00:38~ Kiya Ryokan #KiyaRyokan
01:05~ Walking in the city center (folk craft shops, flag shops, etc.) #FolkCraft #PaperMache #Flags
01:43~ Enjoying festivals (Ushioni Festival, Noryo Night Market, Bon Odori, Fireworks Festival) #UshioniFestival #FireworksFestival
02:50~ Auction at Oura Fish Market #Auction #FishMarket #Oura
03:08~ Scene of making Jako-ten #JakoTen
03:32~ Café #Café
03:44~ Uwajima Castle #UwajimaCastle
04:16~ Kujima #Kujima
05:21~ Scenes of fish farming and pearl farming #Farming #Pearls #Buri #Tai
05:55~ Omaki District #Omaki #TsushimaTown
06:13~ Bullfighting #Bullfighting #BullfightingArena
06:50~ Scene of harvesting mandarin oranges #Mandarins #MandarinOrchard
07:16~ Uwajima Station' where id = 'zCPDNJtQwi99RK1y7n516';
update content_bodies set title = '宇和島に住む ～宇和島に関わりたくなる／住みたくなる／住み続けたくなる', description = '愛媛県宇和島市のブランドムービーは３種類あります。

　宇和島に興味をもっていただいた方が、それぞれの興味の在り処によって、本市との関わり合いをご想像いただけるように、という想いを込めて制作しました。
　実際に本市に暮らしている子育て世代の人たちが、暮らしている人の目線で「宇和島暮らし」の魅力を生の声で紹介する内容になっています。宇和島の「暮らし」に興味がある方におすすめです。
#宇和島#うわじま#宇和島市#ブランドムービー

【参考】各チャプターの概要
　00：00～　　セレクトショップを営む夫婦（宇和島市三間町）　#セレクトショップ#三間
