　03：51頃～　里山暮らしを求めて移住した夫婦（宇和島市津島町）#里山暮らし#移住#津島' where id = 'F9QG29UMK0gFQIYbDTr4O';
update content_bodies set title = 'Living in Uwajima - Wanting to be involved with Uwajima / Wanting to live in Uwajima / Wanting to continue living in Uwajima', description = 'There are three types of brand movies for Uwajima City, Ehime Prefecture.

These were created with the hope that those who become interested in Uwajima can imagine their connection with the city based on their individual interests.
The content features voices from actual residents, particularly those raising children, who introduce the charm of "living in Uwajima" from their perspective. It is recommended for those interested in the "lifestyle" of Uwajima.
#宇和島#うわじま#宇和島市#ブランドムービー

