update content_bodies set title = '吉田くんの『神々のふるさと出雲』第2回「ヤマタノオロチ」', description = '『秘密結社 鷹の爪』の蛙男商会が、日本神話のふるさと・しまねに伝わる出雲神話の紹介映像を制作されています。第2回は「ヤマタノオロチ」。ナビゲートは島根県吉田村（現雲南市）出身のしまねSuper大使吉田くんです。' where id = 'CchU_cnXiCayDoiUfhLlC';
update content_bodies set title = 'Yoshida-kun''s ''The Hometown of the Gods: Izumo'' Episode 2 ''Yamata no Orochi''', description = '''The Secret Society of the Eagle''s Claw'' by Kaeru Otoko is producing an introduction video about the Izumo mythology that is passed down in the hometown of Japanese mythology, Shimane. Episode 2 is ''Yamata no Orochi''. The navigator is Yoshida-kun, the Shimane Super Ambassador from Yoshida Village (now Unnan City) in Shimane Prefecture.' where id = 'lIA94CFK3XKy2qqbLbVzH';
