update content_bodies set title = '[Nagasaki Prefecture Cultural Tourism PR Movie] ''CROSSING NAGASAKI - Intersecting Nagasaki -''', description = 'Filled with the charm of different cultures, the nostalgic culture and scenery of Nagasaki, along with encounters with warm-hearted people, will make your journey special. The full version of ''CROSSING NAGASAKI'' conveys the allure of Nagasaki''s cultural tourism without reservation.

■TABINAGA Travel Nagasaki Study WEB Site
https://tabinaga.jp/' where id = 'AJS7921fnb7Qd30L8Ouu0';
update content_bodies set title = '南紀熊野ジオパーク', description = '紀伊半島南部に位置する、南紀熊野ジオパーク。世界最北の大規模サンゴ群生地を擁するこの海の底の大地は、長い時間の中で地上へ押し上げられてきた。海の底の記憶と、そして大規模な火山活動の痕跡とを刻んだ大地。こうした「過去」が南紀熊野の「現在」の生命や人々の暮らしをつくり出しており、ジオパークという取り組みを通じて「未来」へ伝えられている。

南紀熊野ジオパークWebsite　https://nankikumanogeo.jp/
南紀熊野ジオパークFacebook　https://www.facebook.com/nankikumanogeo/
南紀熊野ジオパークInstagram　https://www.instagram.com/nankikumano_geopark/

==============================
［企画・制作］　和歌山県
［協力］　南紀熊野ジオパーク推進協議会
［制作協力］　株式会社ジオ・ラボ／株式会社KOO
==============================' where id = 'd2g3HUJwKj7Oph0bCQEUs';
update content_bodies set title = 'Nanki Kumano Geopark', description = 'Located in the southern part of the Kii Peninsula, the Nanki Kumano Geopark. This land at the bottom of the sea, which boasts the world''s northernmost large-scale coral reef, has been pushed up to the surface over a long period of time. A land etched with the memories of the ocean''s depths and traces of large-scale volcanic activity. Such ''past'' creates the ''present'' life and the livelihoods of the people in Nanki Kumano, and is being conveyed to the ''future'' through the initiative of the geopark.

Nanki Kumano Geopark Website https://nankikumanogeo.jp/
Nanki Kumano Geopark Facebook https://www.facebook.com/nankikumanogeo/
Nanki Kumano Geopark Instagram https://www.instagram.com/nankikumano_geopark/

==============================
[Planning and Production] Wakayama Prefecture
[Cooperation] Nanki Kumano Geopark Promotion Council
[Production Cooperation] Geo Lab Co., Ltd. / KOO Co., Ltd.
==============================' where id = 'WTLclFbJwZSsNNWHcmRP7';
update content_bodies set title = '大阪の24時間', description = '大阪は素晴らしい観光名所、文化、食べ物でいっぱいです。

この街の刺激的で活気に満ちたシーンは、世界中で知られています。しかし、大阪が知られる無限のアクションと興奮に加えて、訪問者が自然と一体になり、この壮大な都市の歴史を真に感じることができる場所もたくさんあります。

梅田、難波、道頓堀などの人気の観光地から、たこ焼きや寿司などの魅力的な食べ物まで、歴史と文化に富んだ多様な都市を見て、発見してください。象徴的な大阪城から、街の通りにある無限のナイトクラブの電気的な活気まで - これが大阪です。

今すぐ私たちのチャンネルを登録して、大阪とその多くの魅力についてもっと知りましょう！

