update content_bodies set title = 'Route 42 #南紀熊野の旅路', description = '愛車のスーパーカブに乗って颯爽と走り出す女性。Route 42（国道42号線）を走りながら、橋杭岩でSUPを漕いでみたり、勝浦で鮪に舌鼓を打ったり、夕焼けの白浜でウクレレを弾いてみたり・・・南紀熊野の旅路を満喫した最後に、星空の下で心の声が溢れ出す。「南紀熊野が好きだー！」

南紀熊野ジオパークWebsite　https://nankikumanogeo.jp/
南紀熊野ジオパークFacebook　https://www.facebook.com/nankikumanogeo/
南紀熊野ジオパークInstagram　https://www.instagram.com/nankikumano_geopark/

