update content_bodies set title = 'Route 42 #Journey through Nanki Kumano', description = 'A woman rides her beloved Super Cub and sets off with a flourish. While traveling on Route 42 (National Route 42), she tries stand-up paddleboarding at Hashikui-iwa, enjoys tuna in Katsuura, and plays the ukulele at sunset in Shirahama... After fully enjoying her journey through Nanki Kumano, her heartfelt voice spills out under the starry sky. "I love Nanki Kumano!" 

