update content_bodies set title = '鳥取山中に眠る天空の要塞「若松鉱山」紹介Ｍｏｖｉｅ', description = '若松鉱山は、わずか30年前まで採掘が行われていた日本有数のクロム鉱山。産出されたクロムは耐火煉瓦の原料となり、この地域一帯で日本のクロム需要のほとんどを賄っていた時代もありました。
1995年の閉山となりましたが、今も採掘、選鉱、破砕が行われていた当時の様子がそのまま残る日本では数少ない鉱山跡で平成21年（2009年）に、経済産業省「近代化遺産群 続33」に選定されています。

動画制作クリエイター：
Takatan　https://twitter.com/FriendTK　https://www.instagram.com/friend_tk/

コーディネーター：
Saho　https://www.instagram.com/sanzyuyon/　https://twitter.com/urbex_34

制作：
多里の鉱山を語り継ぐ会、特定非営利活動法人J-heritage' where id = 'CbN11e8Qji3lrhxjJyq85';
update content_bodies set title = 'The Sky Fortress ''Wakamatsu Mine'' Sleeping in the Tottori Mountains Introduction Movie', description = 'Wakamatsu Mine is one of Japan''s leading chrome mines, where mining was conducted until just 30 years ago. The extracted chrome was used as a raw material for fireproof bricks, and there was a time when it supplied most of Japan''s chrome demand in this region.
Although it closed in 1995, it remains one of the few mine sites in Japan where the conditions of mining, sorting, and crushing from that time are still preserved. In 2009, it was selected as part of the Ministry of Economy, Trade and Industry''s ''Modernization Heritage Group Continued 33''.

Video Creator:
Takatan  https://twitter.com/FriendTK  https://www.instagram.com/friend_tk/

Coordinator:
