笠懸神事　10月第3日曜日
笠懸とは、日本書紀にも登場する騎射のひとつ
流鏑馬のような射手にとって水平な的だけでなく、右下方・左下方の地上低く立てられた的を射るなど、より実践的で高い技量を要する弓馬術です
当神社においては、鎌倉時代 後鳥羽上皇が笠懸を行った記録が残り、平成17年からは大日本弓馬会武田流のご奉仕により毎年斎行されています

