update content_bodies set title = '[Kyoto Kamigamo Shrine] Gigensai Offering Event February 11', description = 'One of the oldest shrines in Kyoto, Kamigamo Shrine
The entire precinct is registered as a World Heritage site, preserving its appearance unchanged since the Heian period.

Gigensai Offering Event February 11
Gigensetsu (National Foundation Day) marks the day when Emperor Jimmu ascended to the throne as the first emperor at Kashihara Palace in Yamato Province, celebrating the founding of Japan. 
At this shrine, the Gigensai ceremony will be held from 10 AM, praying for the prosperity of the imperial family and the peace of the nation.
Various offering events such as kemari, kendo, karate, and iaido will take place in the shrine precincts.

