Sakura
Basking in the warm spring sun, the cherry blossoms bloom beautifully.
The gentle sound of a small stream and the chirping of birds, along with the cherry blossom petals dancing in the soft breeze, bring peace to the heart amidst the timeless spring scenery.
From late March to mid-April, various types of cherry blossoms, including the famous "Gosho Sakura" and "Saiou Sakura," reach their peak bloom in succession.

