update content_bodies set title = '【春】真庭PR映像「Spring of Maniwa Okayama Japan」観光 PV', description = '岡山県真庭市・新庄村の春の映像です。里山の中に咲く桜をごらんください。真庭（真庭市・新庄村）は、岡山県の北部 鳥取県との境に位置し、昔から里山とともに生きてきました。蒜山高原や湯原温泉などの観光地もあり、さまざまな風土と自然に恵まれた地域です。冬が終わりすこし温かくなると、あちらこちらで桜が咲き始め、山々が華やかになっていきます。南北に長い真庭は約一ヶ月にわたって桜が楽しめます。

【秋】春真庭PR映像「Autumn of Maniwa Okayama Japan」観光 PV
・https://youtu.be/ctyGRguN9l0

【冬】真庭PR映像「Winter of Maniwa Okayama Japan」観光 PV
・https://youtu.be/YgOuy7U42JM

【真庭の観光情報はこちら↓↓↓】
真庭観光局公式サイト 真庭観光WEB

https://www.maniwa.or.jp/' where id = 'UKICrvPg89YMJGowqq_En';
update content_bodies set title = '[Spring] Maniwa PR Video ''Spring of Maniwa Okayama Japan'' Tourism PV', description = 'This is a spring video from Maniwa City and Shinjo Village in Okayama Prefecture. Please enjoy the cherry blossoms blooming in the satoyama. Maniwa (Maniwa City and Shinjo Village) is located in the northern part of Okayama Prefecture, bordering Tottori Prefecture, and has lived in harmony with the satoyama since ancient times. It is a region blessed with various climates and nature, featuring tourist spots such as Hiruzen Plateau and Yubara Onsen. As winter ends and it becomes a little warmer, cherry blossoms begin to bloom here and there, and the mountains become vibrant. The long north-south stretch of Maniwa allows for about a month of cherry blossom enjoyment.' where id = 'C4RtpXxabMEW9wPt2Pv_U';
update content_bodies set title = '【秋】真庭PR映像「Autumn of Maniwa Okayama Japan」観光 PV', description = '岡山県真庭市・新庄村の秋の映像です。色づく里山をごらんください。

真庭（真庭市・新庄村）は、岡山県の北部 鳥取県との境に位置し、昔から里山とともに生きてきました。蒜山高原や湯原温泉などの観光地もあり、さまざまな風土と自然に恵まれた地域です。

肌寒さが増してくると、里山が徐々に色づいてまいります。美甘渓谷や神庭の滝などの紅葉スポットやコスモスなどの秋の花が楽しめます。

