update content_bodies set title = '[Autumn] Maniwa PR Video ''Autumn of Maniwa Okayama Japan'' Tourism PV', description = 'This is an autumn video of Maniwa City and Shinjo Village in Okayama Prefecture. Please enjoy the colorful satoyama.

Maniwa (Maniwa City and Shinjo Village) is located in the northern part of Okayama Prefecture, bordering Tottori Prefecture, and has lived in harmony with the satoyama since ancient times. It is a region blessed with various climates and nature, featuring tourist spots such as Hiruzensan Plateau and Yubara Onsen.

As the chill in the air increases, the satoyama gradually begins to change color. You can enjoy autumn foliage spots like Mikama Valley and Kanba Falls, as well as autumn flowers like cosmos.

[Winter] Maniwa PR Video ''Winter of Maniwa Okayama Japan'' Tourism PV
・https://youtu.be/YgOuy7U42JM

