update content_bodies set title = '【冬】真庭PR映像「Winter of Maniwa Okayama Japan」観光 PV', description = '岡山県真庭市・新庄村の冬の映像です。雪の楽しみや、寒い時期ならではの手仕事が行われています。

真庭（真庭市・新庄村）は、岡山県の北部 鳥取県との境に位置し、昔から里山とともに生きてきました。蒜山高原や湯原温泉などの観光地もあり、さまざまな風土と自然に恵まれた地域です。

北部は雪が積もり、スキー・スノーシューなど雪を楽しむことができ、雪恋まつりは幻想的なキャンドル風景に魅了されます。お酒の仕込みや竹細工など、寒い時期の仕事も行われ、昔から続く生活も垣間見えます。

