update content_bodies set title = 'Japan''s Only Enclave Village ''Kitayama Village, Wakayama Prefecture'' - Scenic Wilderness and River Adventures', description = 'This is the official promotional video of **Kitayama Village** (きたやまむら), the ''only enclave village in Japan'' located in Wakayama Prefecture.

We have condensed special experiences that can only be enjoyed here, including the beautiful nature of the hidden realms of the Kii Mountains, thrilling rafting, and the 600-year history of sightseeing river rafting.

