update content_bodies set title = '【360°VRで体験する】北山村の風景', description = '[HMD装着視聴の場合の年齢制限：10歳以上]＊通常のスクリーン画面でも360°視聴操作可能です。

日本で唯一の飛び地の村である「和歌山県北山村」は紀伊半島の山奥にある小さな小さな村。
しかしここには驚くほどユニークな魅力が沢山詰まっています。

丸太いかだに乗って川を下る「北山川観光筏下り」に希少な柑橘「じゃばら」の原産地であり、そして秘境の美しい大自然に根付いた風景を眺められる。
心がどこかふっと軽くなるような山間地の景色をVR映像でお楽しみください。

#北山村　#日本唯一の飛び地村　#北山川　#美しい村' where id = 'nhtpguq7ezJcj0OA8Es9Z';
