update content_bodies set title = '瀬戸内無人島図鑑　芸予諸島の多島美　四十島　Yosojima - Beauty of scattered islands in Geiyo Islands', description = '四十島は、瀬戸内海西部の広島・愛媛にまたがって点在する島群である芸予諸島に属する無人島です。
島の大きさは4,200㎡ほどで、嘴のように突出した岩場や洞窟、こじんまりしたビーチなどが特徴です。
瀬戸内を代表する島群である芸予諸島の風景と初夏の四十島の美しい姿をお楽しみください。

Yoso Island is an uninhabited island belonging to the Geiyo Islands, which is a group of islands scattered across Hiroshima and Ehime in the western part of the Seto Inland Sea.
The island is about 4,200 ㎡ in size and features beak-like protruding rocks, caves and small beaches.
Please enjoy the scenery of the Geiyo Islands, which is a representative island group of Setouchi, and the beautiful appearance of Yoso Island in early summer.

