update content_bodies set title = '長浜神社 Nagahama - Shrine〜出雲の国の始まりを記した国引き神話の主役を祀る神社〜', description = '御祭神は八束水臣津野命(やつかみずおみつぬのみこと)。
国引き神話の主人公で、その昔、八束水臣津野命は、
『出雲国は細長い布切れのような国だな、最初に国を
小さく作り過ぎてしまった。だから作り足して大きくしよう』
と思われました。
杵築の岬、狹田の国、闇見の国、美保の岬と四度にわたる
国引きを終えられ、国土生成をなされた八束水臣津野命
は出雲国の総鎮守、国引きの神として、長浜に祀られました。
国引き神話の故事により、八束水臣津野命は
国を引き寄せ、人を引き寄せ、幸を引き寄せた
偉大な神様として、武運長久、勝利を引き寄せる
神として広く信仰されています。

Enshirneed deity is Yatsukamizuomitsunu no Mikoto.
A long time ago, Yatsukamizuomitsunu no Mikoto think
 Izumo Province is like a long strip of cloth, and at first
 I made the country too small. So let''s make it and make it 
bigger. "
Kiduki''s cape, Sada''s country, Kurami''s country, Miho''s cape and 
four times four times after finishing the Land dragging, 
Yatsukamizuomitsunu no Mikoto was enshrined in Nagahama
 as the god of Land dragging,  the general guardian of Izumo Province, 
who had completed the created the land.
Due to the story of the Kunibiki myth, Yatsukamizuomitsunu no Mikoto
is widely worshiped as a great god who attracted the country,
attracted people, and attracted happiness,
 and a god who attracted victory.

