update content_bodies set title = '金山の道、百年の光。【Yamagata - Tohoku / Japan travel】', description = '山形県金山町　町制施行100周年記念映像

「金山の道、百年の光。」

令和7年1月1日　
100周年という節目を迎える金山町

この100年間で生まれたもの　失したもの　
変わらずに在るもの　刻々と変わりゆくもの

山は　木は　清き水の流れる川は　
どんな100年を見てきただろうか

土地に伝わる幻のいきものは　
この100年を見ているだろうか

金山の100年を想う人たちが立つ場所には　
どんな風が吹き　
どんな空が見えるだろうか

令和6年の秋
金山の100年を祝う「百年祭」をひらく

その日に向かうまでに　
金山の四季や　
街並みの移り変わり　

林業などの仕事や歴史　

町に関わる人々のくらしや　
言葉にふれていく


