update content_bodies set title = '【Yamagata - Tohoku / Japan travel】K-hour clips', description = '「K-hour movie」総集編を公開します。 

「K-hour」では金山にある“暮らし”や“日常”を切り取り、金山を訪れる時に同じ日常をみていただくために動画を製作しました。

金山町には金山にしかない時間が流れています。 それは穏やかでゆっくりした、訪れる人をあたたかくつつみ込むようなときの流れ。 澄んだ空気に触れ、山の匂いを感じ、溢れる笑顔が自然とある。 営みに寄り添うように日が暮れ、一日を照らし出すようにまた日が昇る。 心をありのままに過ごす時間。

これまで金山の四季から紡いできた金山の時間をひとつの作品にまとめました。

【Birds flyhigher, and K-hour is going on】

これからもつづく「金山の時間」を少しでも多くの方に、見て感じてもらえたら嬉しいです。

主宰：山形県金山町
統括プロデューサー：吉野敏充
プロデューサー：渡辺然
ディレクター / エディター：佐藤鈴華
出演：阿部優奈・これまでK-hour MVに参加頂いた皆さん
制作：Strobelight 

