・K-hour‐community-reactivating cooperator squad‐： https://www.youtube.com/watch?v=vLJ2tPBIb6c&t=3s 
・K-hour‐winter‐：https://www.youtube.com/watch?v=XOPK9-sl0E8&t=95s
・K-hour‐design school‐：https://www.youtube.com/watch?v=4gYYU6M1t3I

