update content_bodies set title = '[Yamagata - Tohoku / Japan travel] K-hour ‐community-reactivating cooperator squad‐', description = 'We will release the "K-hour movie" featuring the community revitalization cooperation team.

In the "K-hour project," we are producing videos that capture the "lifestyle" and "everyday life" in Kaneyama, allowing visitors to experience the daily life of Kaneyama.

Last year, Maki Honma joined the community revitalization cooperation team in Kaneyama. Currently, she is engaged in various activities to build new relationships with people outside the town and to create fans of Kaneyama.

In this video, you will see the connections formed while living and working in Kaneyama as a community revitalization cooperation team member. Although she is not from the area, she feels and lives in Kaneyama as if it were her hometown, even more than her actual hometown. 

Please feel the "time of Kaneyama" that is being created through her involvement with the town.

