update content_bodies set title = '[Yamagata - Tohoku / Japan travel] K-hour -summer-', description = 'We are releasing the summer edition of the ''K-hour movie''.

In ''K-hour'', we capture the ''lifestyle'' and ''everyday life'' in Kaneyama,
creating videos so that visitors can see the same daily life when they come to Kaneyama.

In Kaneyama, there flows a time that can only be found here.

