update content_bodies set title = '【3日目】2泊3日で周遊！岡山を味わい尽くす女子二人旅', description = 'みなさんは、岡山県の魅力をどのくらい知っているでしょうか。
古き良き街並みを堪能できる「倉敷」を思い出す人が多いのでは？　でもそれだけじゃないんです！

