update content_bodies set title = '[Suntopia Okayama Soja] Let''s see the town and facilities of Soja from the sky!', description = '◆[Official] Suntopia Okayama Soja Glamping
http://www.suntopia.info/

A resort hotel located in "Kibiji," a treasure trove of ancient ruins.
Surrounding the hotel are countless burial mounds represented by the two major tombs, "Zozan Kofun" and "Sakuyama Kofun," as well as valuable cultural properties and ruins that tell the story of the prosperity of the time, such as Bichu Kokubunji, the remains of a nunnery, and Onigajo.
This is a lodging-type leisure facility equipped with accommodations, bridal services, meetings, banquets, restaurants, day-use baths, a leisure pool (in summer), a gymnasium, tennis courts & futsal courts, and ground golf, among others.
The glamping facility opened in August 2021!!

For more details, visit the official website or check out the experience article by a local writer below!

◆~Local writers share the charm of Okayama!~ ''Okayama Travel''
【NEW Open! A glamping spot where you can enjoy both the pool and large public bath "Suntopia Okayama Soja"】
