update content_bodies set title = '【牛窓研修センター カリヨンハウス】離島で自然体験が充実！空から絶景と施設を見てみよう！', description = '【公式】牛窓・研修センター カリヨンハウス 
https://carillon-house.com/

自然体験と研修に集中できる環境を備えた研修施設

日本のエーゲ海として名高い牛窓（岡山県瀬戸内市）に浮かぶ前島に研修宿泊施設カリヨンハウスがあります。オリーブと蒼い海の織りなすのどかな瀬戸の風景は息をのむ美しさです。250名収容の宿泊棟、研修棟、大ホールからなるカリヨンハウスを中核施設とし、広大な敷地には天文館・多目的工房・備前焼登り窯などを備え、学習・野外・マリンスポーツ・文化体験など多彩なアクティビィティやプログラムを行うための最適な環境を整備しております。また、企業研修等の宿泊型セミナ－ハウスとしてご利用いただくとともに地域イベントのサポート施設としての役割も担っています。

空から離島の大自然と、瀬戸内海の多島美、海沿いに建つ施設の全容をご覧ください！

◆岡山観光WEB　スポット情報
https://www.okayama-kanko.jp/reserve/12052' where id = 'wcr2dnmpqrlcWb-rj8W51';
update content_bodies set title = '[Ushimado Training Center Carillon House] A Rich Natural Experience on an Island! Let''s See the Spectacular View and Facilities from the Sky!', description = '[Official] Ushimado Training Center Carillon House
https://carillon-house.com/

A training facility equipped with an environment conducive to nature experiences and training.

On Maejima Island, floating in Ushimado (Setouchi City, Okayama Prefecture), known as the Aegean Sea of Japan, is the training accommodation facility Carillon House. The tranquil Seto landscape woven with olive trees and the blue sea is breathtakingly beautiful. With Carillon House as the core facility, which consists of a lodging building that accommodates 250 people, a training building, and a large hall, the vast grounds are equipped with an observatory, multipurpose workshop, and Bizen pottery climbing kiln, providing an optimal environment for a variety of activities and programs such as learning, outdoor activities, marine sports, and cultural experiences. It also serves as a lodging seminar house for corporate training and plays a role as a support facility for local events.

See the great nature of the remote island from the sky, the beauty of the many islands in the Seto Inland Sea, and the full view of the facilities along the coast!

◆ Okayama Tourism WEB Spot Information
https://www.okayama-kanko.jp/reserve/12052' where id = 'yyt3H_6Mz6PlNLKlJ0mxA';
update content_bodies set title = '瀬戸内市牛窓「前島」でサイクリング体験', description = '日本のエーゲ海とも言われている瀬戸内市牛窓。牛窓港からフェリーで約5分の場所にある「前島」は、別名「緑島」と呼ばれ、美しい松林などの自然林が繁り、キャベツ畑が広がる、緑豊かな島で、島全体が国立公園に指定されています。

「まえじま夕日公園」や大坂城再建の際に石垣を切り出した丁場の跡である「大坂城築城残石群」からの景色は絶景！レンタサイクルで島を散策してみよう♪

また、前島を含む牛窓周辺は「日本の夕陽百選」に選ばれており、オレンジ色に染まる瀬戸内の夕景は旅の思い出になること間違いなし！

【島でしか体験できない！瀬戸内の島時間】
https://www.okayama-kanko.jp/feature/island/' where id = 'OdgsrvHHMGPgEicOME5Jw';
update content_bodies set title = 'Cycling Experience on Maejima Island in Ushimado, Setouchi City', description = 'Ushimado, Setouchi City, is often referred to as the Aegean Sea of Japan. Located about 5 minutes by ferry from Ushimado Port, Maejima, also known as ''Green Island,'' is a lush island with beautiful pine forests and expansive cabbage fields, and the entire island is designated as a national park.

The views from ''Maejima Sunset Park'' and the ''Osaka Castle Construction Remains,'' where stones were quarried during the reconstruction of Osaka Castle, are breathtaking! Let''s explore the island by renting a bicycle! 

Additionally, the area around Ushimado, including Maejima, has been selected as one of the ''One Hundred Best Sunsets in Japan,'' and the orange-hued sunset over Setouchi is sure to become a cherished memory of your trip!

【Experience Only on the Island! Setouchi Island Time】
https://www.okayama-kanko.jp/feature/island/' where id = 'We64XGrtcfM9vsSSFZ3hr';
update content_bodies set title = '【農家民宿みっちゃん】岡山の中心〈吉備中央町〉で季節の郷土料理を味わい農業体験‼', description = '農家民宿みっちゃん外観は、お花に囲まれた可愛い作り。それもそのはずで、みっちゃんは25年にわたってお花の寄植えをしてきたベテランです。シンプルなようで奥が深い寄植えに触れれば、ご自身の芸術的感性も磨かれることでしょう。また職人気質の旦那さんが作る工芸品も随所に置かれているので、手に取れるものには触りながら同じく感性を刺激してみてください。

◆岡山観光WEB　宿泊施設情報【農家民宿みっちゃん】
https://www.okayama-kanko.jp/reserve/12210

【ココロ晴れやか。晴れの国おかやま農家民宿】
街の中で毎日、時間に追われているのなら、ときどき里山や里海に来て、時間を忘れてみませんか。
清々しい空気と自然いっぱいの中、気持ち安らぐ宿や自然とふれあう農林漁業体験、あったかい人々の飾らず、気どらないおもてなしが待っています。
岡山県は晴れの国。心と身体が、きっとハレバレしますよ。
https://www.okayama-kanko.jp/feature/nouhaku/top


