update content_bodies set title = '白石島 盆踊り（白石踊）【岡山県笠岡市】', description = '源平水島合戦の戦死した人を弔うために始められたといわれる、島に伝わる踊り。8月13日～16日の夜に行われる古式ゆかしい盆踊りです。ひとつの口説き（音頭）に合わせて、男踊、女踊など十数種類もの踊りを輪になって舞うのが特徴で、他に類を見ない踊りの形式から、国指定の重要無形民俗文化財に選定されています。

2022年11月30日、お囃子にあわせて踊る全国各地の民俗芸能「風流踊」のひとつとして、真庭市蒜山の「大宮踊」とともにユネスコの無形文化遺産に登録（岡山県の「大宮踊」「白石踊」をはじめ、日本国内の24都府県41件で構成）されました。

※地域の盆踊りのため、8月13日～16日の当日は衣装を着けての踊りは行われません。

岡山県観光公式サイト【岡山観光WEB】
イベント情報：https://www.okayama-kanko.jp/event/12621

