update content_bodies set title = 'Shiraishijima Bon Odori (Shiraishi Dance) [Kasaoka City, Okayama Prefecture]', description = 'It is said that this dance, which has been passed down on the island, was started to mourn those who died in the Genpei Battle of Mizushima. This traditional Bon Odori is held from the night of August 13 to 16. Characterized by dancing in a circle to a single chant (ondo), it features a variety of dances, including male and female dances, making it a unique form of dance that has been designated as an Important Intangible Folk Cultural Asset by the national government.

On November 30, 2022, it was registered as one of the folk performing arts called ''Furyu Odori'' that dance to the accompaniment of traditional music, along with ''Omiya Odori'' from Hiruzan, Maniwa City, as a UNESCO Intangible Cultural Heritage (composed of 41 items from 24 prefectures in Japan, including Okayama''s ''Omiya Odori'' and ''Shiraishi Dance'').

*Please note that traditional costumes will not be worn during the local Bon Odori on August 13 to 16.

Okayama Prefectural Official Tourism Site [Okayama Tourism WEB]
Event Information: https://www.okayama-kanko.jp/event/12621

Related Articles
~Local writers share the charm of Okayama!~ [Oka Tabi]
I experienced the ''Shiraishi Dance'' of Shiraishijima, Kasaoka City, a UNESCO Intangible Cultural Heritage!
https://www.okayama-kanko.jp/okatabi/1113/page' where id = 'zqCVaZyR9n0taj1jOzYB2';
update content_bodies set title = 'ノスタルジック！ 昭和レトロな駅舎が残る【柵原ふれあい鉱山公園】', description = '柵原ふれあい鉱山公園／柵原鉱山資料館
