《昭和へタイムトリップ！ レトロな鉄道体験ができる》

旧片上鉄道の吉ケ原（きちがはら）駅舎と操車場のあった場所に作られた柵原ふれあい鉱山公園。園内には1955（昭和30）年頃の鉱山の様子や暮らしぶりを再現した柵原鉱山資料館や、実際に使用していた車両（11両）の展示があり、見学が可能です。鉄道ファンや小学生の自由研究にも人気のスポットです。

