update content_bodies set title = 'Nostalgic! Showa Retro Station Remains at [Sakahara Fureai Mine Park]', description = 'Sakahara Fureai Mine Park / Sakahara Mine Museum
Yanahara Fureai Mine Park / Yanahara Mine Museum

《Time Travel to the Showa Era! Experience Retro Railways》

Sakahara Fureai Mine Park was built on the site of the former Katanaka Railway''s Kichigahara Station and freight yard. Inside the park, you can find the Sakahara Mine Museum, which recreates the mining conditions and lifestyle around 1955 (Showa 30), as well as exhibits of actual vehicles (11 units) that were used, available for viewing. It is a popular spot for railway enthusiasts and elementary school students'' research projects.

