update content_bodies set title = '오카야마 일본 전편', description = '일본・오카야마현의 매력적인 관광지를 소개합니다. 오카야마현에는 국가지정 전통적건조물군 보존지구인쿠라시키 미관지구, 일본3대 명정원의 하나인오카야마 고라쿠엔등 많은 관광명소가 있습니다.

~「오카야마 COOL!」을 발신하는 외국어 사이트~

오카야마 현에서는 오카야마의 관광, 맛집, 이벤트 정보를 게재한 홈페이지를 신설했습니다. 현재 오카야마에서 살고 있는 한국 사람들이 직접 보고 느낀 것을 쓴 홈페이지입니다. 
