update content_bodies set title = 'Hokkaido’s Niagara Falls', description = 'This waterfall, known as Niagara Falls in Hokkaido (in the Otaki area of Date City), is accessible via a trail course of about 6 km along the Nagauru River through the forest from the Otaki General Sports Park.
You can enjoy the view of the 3-meter drop and 30-meter width of the Otaki Niagara Falls, as well as the scenery of Mount Tokushunbetsu.' where id = '41IptfvSEmjWPAR_HAhTE';
update content_bodies set title = 'Active Volcano Walk  - Summit of Mt.Usu -', description = '活火山を歩く。
有珠山外輪山からは、火口原内部にそびえる小有珠、大有珠、オガリ山、有珠新山などの溶岩ドームが見える。

Active Volcano Walk (Summit of Mt. Usu)
A walk around the out rim of Mt. Usu grants a view of Mt. Ko-usu towering out of the crater, and the surrounding volcanic formations such as Mt. Ogari, Mt. Ō-usu and the Usushinzan lava dome.' where id = 'fRrh02zIXhcDJdN-2gs--';
update content_bodies set title = 'Active Volcano Walk - Summit of Mt. Usu -', description = 'A walk around the out rim of Mt. Usu grants a view of Mt. Ko-usu towering out of the crater, and the surrounding volcanic formations such as Mt. Ogari, Mt. Ō-usu and the Usushinzan lava dome.' where id = 'fy-ndub-Ot4XiRrle6Jmf';
update content_bodies set title = 'Hokkaido fisherman in spring', description = '北海道の内浦湾にある洞爺湖町では、ホタテの養殖が盛んだ。
ユネスコの世界遺産にも登録されているこの地域は、100年の間に４度も噴火を繰り返す「有珠山」や、噴火によって形成されたカルデラ湖「洞爺湖」があり、その噴火によって降り注ぐ火山灰はやがて豊富な土壌となり、川からはミネラル豊富な水が海に注がれる。
そんな美しい海で育ったホタテの味は絶品である。

特に春は、「耳づり」と言われる独特な養殖方法に多くの人手が必要なため、小さな漁業町は活気づく季節である。' where id = 'Ogn9pYpGqmXURqswhI6n4';
update content_bodies set title = 'Hokkaido fisherman in spring', description = 'In Toyako Town, located in Uchiura Bay, Hokkaido, scallop farming is thriving.
This region, which is registered as a UNESCO World Heritage site, features Mount Usu, which has erupted four times over the past 100 years, and Lake Toya, a caldera lake formed by volcanic eruptions. The volcanic ash that falls from these eruptions eventually becomes rich soil, and mineral-rich water flows from the rivers into the sea.
The taste of scallops raised in such beautiful waters is exquisite.

Especially in spring, the unique farming method known as "mimizuri" requires a lot of manpower, making this small fishing town a lively place during the season.' where id = 'n-ta__AGZdj7N0cAB1Cfi';
update content_bodies set title = 'NIIGATA ASMR_01 トレッキング篇', description = '野山をトレッキングシューズでザクザク歩く。柔らかな日差しと風を頬に感じながら、野鳥のさえずり、虫の音、小川のせせらぎが賑やかに聞こえてくる。池や滝の水辺の空気はどこまでも清々しい。そんな森林の香りまで届きそうな没入感を糸魚川&妙高のASMR動画でお楽しみください。

