update content_bodies set title = '埼玉県熊谷市グルメCMシリーズ『五家宝（ごかぼう）編』', description = '埼玉県熊谷市グルメCMシリーズ『五家宝（ごかぼう）編』です。

きな粉と、米粉からできたパフ状のたね、そして水あめだけでつくられるシンプルなお菓子が『五家宝』です。
埼玉県の３大銘菓にも数えられる『五家宝』ですが、機械による大量生産に向かず、今でも職人の手によりひとつひとつ丁寧にその伝統が引き継がれています。

https://www.oideyo-kumagaya.com/cate-gourmet/16470/

☆100年フード認定☆
五家宝は文化庁選定の“100年フード”に江戸時代から続く「伝統部門」として令和3年度に認定され、さらに有識者特別賞を受賞しました。' where id = 'VyTRHuLtYzIypH6QyT7c1';
update content_bodies set title = 'Kumagaya City, Saitama Prefecture Gourmet CM Series ''Gokabou Edition''', description = 'This is the Kumagaya City, Saitama Prefecture Gourmet CM Series ''Gokabou Edition''.

''Gokabou'' is a simple confection made only from soybean flour, puffed rice flour, and syrup.
Although ''Gokabou'' is counted among the three major confections of Saitama Prefecture, it is not suitable for mass production by machines, and its tradition is still carefully passed down by artisans, one by one.

https://www.oideyo-kumagaya.com/cate-gourmet/16470/

☆100-Year Food Certification☆
Gokabou was certified as a ''100-Year Food'' in the traditional category, which has continued since the Edo period, by the Agency for Cultural Affairs in the fiscal year 2021, and also received a special award from experts.' where id = 'SPtNDT9nDMjg6YMvJUFRf';
update content_bodies set title = '埼玉県熊谷市グルメCMシリーズ『雪くま編』', description = '埼玉県熊谷市グルメCMシリーズ『雪くま編』です。

荒川が関東平野に流れ込む扇状地に広がる熊谷市は、伏流水による美味しい地下水が豊富で、その美味しい熊谷の水をつかった氷を、ふわふわに仕上げたかき氷が『雪くま』です。
日本一の夏の暑さが、かき氷をさらに美味しくしてくれます。

https://www.oideyo-kumagaya.com/cate-gourmet/361/' where id = 'AHrw3dpYHaE58-aokKXuL';
update content_bodies set title = 'Kumagaya City Gourmet CM Series ''Yuki Kuma Edition''', description = 'This is the Kumagaya City Gourmet CM Series ''Yuki Kuma Edition''.

Kumagaya City, which spreads across the fan-shaped alluvial plain where the Arakawa River flows into the Kanto Plain, is rich in delicious underground water from spring water. The fluffy shaved ice made with this delicious Kumagaya water is called ''Yuki Kuma''.
The hottest summer in Japan makes the shaved ice even more delicious.

https://www.oideyo-kumagaya.com/cate-gourmet/361/' where id = 'BVmhEblO8S7DHzHIPxfdm';
