update content_bodies set title = '【熊本県和水町】まちとぼくとの物語～あなたに、なごみを。～（秋編）', description = '和水町ホームページ：https://www.town.nagomi.lg.jp/
和水町公式Instagram：https://www.instagram.com/nagomitown?utm_source=ig_web_button_share_sheet&igsh=ZDNlZDc0MzIxNw==


熊本県和水町（なごみまち）で実際に暮らす、高校三年生が主人公。
彼は来年の春に町外への進学を控えており、生まれ育ってきた
和水町を旅立つまでの1年間の軌跡をドキュメンタリーで辿るムービーの夏篇です。
和水町の美しい季節を四季で追いかけながら、そこで口にする豊かな食べものや飲みもの、
あたたかい人たちから生まれる文化やイベント等をリアリティをもって描き出します。
1人の高校生が成長していく姿と、彼やそこに住まう人々を
いつでも支えてきた和水町らしい魅力が響き合う映像に仕上げました。


■この動画で紹介される和水町の魅力
＜秋＞
・金栗四三翁マラソン大会（歴史・イベント）
・山太郎ガネ（食）
・米（食）

