熊本県和水町は熊本県北西部、福岡県との県境に位置し、南北約19キロ、東西約9キロ、面積は約98平方キロメートル。人口は約9,000人です' where id = 'kOeCp0IQFQpYDoVqs8_SG';
update content_bodies set title = '[Nagomi Town, Kumamoto Prefecture] The Story of the Town and Me - To You, with Warmth. - (Autumn Edition)', description = 'Nagomi Town Official Website: https://www.town.nagomi.lg.jp/
Nagomi Town Official Instagram: https://www.instagram.com/nagomitown?utm_source=ig_web_button_share_sheet&igsh=ZDNlZDc0MzIxNw==

The protagonist is a high school senior living in Nagomi Town, Kumamoto Prefecture.
He is preparing to move out of town for further studies next spring, and this is the summer edition of a documentary tracing his journey over the year until he leaves his beloved Nagomi Town.
While following the beautiful seasons of Nagomi Town, the film realistically depicts the rich food and drinks enjoyed there, as well as the culture and events born from the warm-hearted people.
It culminates in a visual representation of a high school student growing up, resonating with the charm of Nagomi Town that has always supported him and its residents.

■ The Charms of Nagomi Town Featured in This Video
<Autumn>
- Kanekuri Shiso Marathon (History & Events)
- Yamataro Gane (Food)
- Rice (Food)

