新潟市　信濃川と萬代橋　進化するみなとまち新潟市

　遙か甲武信ヶ岳を水源とし、長野千曲川を経て日本海へと流れ込む信濃川。新潟平野を日本一の稲作の地とし、人々の生活を潤してきたその流れは萬代橋を境に、ここ新潟市で河としての役割を終え、一転して間もなく開港１５０年を迎える新潟西港へとその役割を変える。そして新潟市はウォータフロント・シティーとして、今もなお進化し続けている。

公益社団法人 新潟県観光協会
〒950-8570
新潟県新潟市中央区新光町4番地1
電話番号：025-283-1188
ファックス番号：025-283-4345
