update content_bodies set title = '[NIIGATA-SORADORI] Shinano River and Bandai Bridge - The Evolving Port City of Niigata', description = 'Niigata Tourism Navigation [NIIGATA-SORADORI]
Niigata City - Shinano River and Bandai Bridge - The Evolving Port City of Niigata

The Shinano River, originating from the distant Kobushin Mountain, flows through the Chikuma River in Nagano and into the Sea of Japan. This river, which has made the Niigata Plain the top rice-producing area in Japan and enriched the lives of its people, reaches its end as a river at Bandai Bridge, transforming its role as it approaches the Niigata West Port, which will soon celebrate its 150th anniversary. Niigata City continues to evolve as a waterfront city.

Public Interest Incorporated Association Niigata Prefectural Tourism Association
