update content_bodies set title = '【NIIGATA-SORADORI】福島潟　朝霧の伝統漁　新潟市', description = 'にいがた観光ナビ【NIIGATA-SORADORI】
新潟市　福島潟　朝霧の伝統漁
　新潟市北区にある福島潟は、２００種を超える渡り鳥の飛来地として、市民のみならず多­­くの愛鳥家に親しまれている。また、オニバスを始めとした希少植物の北限生息地とし­て­も知られる。そこ福島潟で、古くから行われている伝統漁は、早朝の湖面を滑るよう­に進­む潟舟。朝霧に溶けこむような漁師達の影は、豊かな潟の自然環境と共に残すべき­新潟の­姿である。

