update content_bodies set title = '【NIIGATA-SORADORI】大したもん蛇まつり　大蛇に込めた村人の想い　関川村', description = 'にいがた観光ナビ【NIIGATA-SORADORI】
大したもん蛇まつり　大蛇に込めた村人の想い　関川村

　ギネスにも認定された「世界一長い竹とわらで作られた大蛇」は、村に残る「大里峠(おおりとうげ)」という大蛇伝説をテーマに、昭和42年に発生した羽越水害での惨事を後世に伝えるべく始められた祭りのシンボルである。大蛇の長さは、羽越水害の発生した8月28日に因んで82.8mとなっている。巨大な大蛇がうねる姿や役場前で巨大なとぐろを巻く姿は圧巻である。

