update content_bodies set title = '【NIIGATA-SORADORI】日本の風情を感じて　弥彦公園・もみじ谷の紅葉　弥彦村', description = '弥彦公園は、日本の風情を感じられる公園。園内にあるもみじ谷では、朱色に塗られた観月橋と赤や黄色に染まるもみじが織りなす景色を楽しめる。' where id = 'Khxe8rlvlwTAx1iTPMm2y';
