update content_bodies set title = '[NIIGATA-SORADORI] Niigata Prefecture''s 100 Scenic Spots: Towering Cliffs and Autumn Foliage at Yagigahana, Sanjo City', description = 'The towering cliffs rise about 200 meters. Peregrine falcons inhabit the area, and their breeding inland is extremely rare. Not only is it designated as a natural monument of the prefecture as the ''Breeding Ground of Peregrine Falcons at Yagigahana,'' but it has also been selected as one of Niigata Prefecture''s 100 Scenic Spots due to its magnificent landscape.' where id = 'zf1gsO145zGVIlcmE9UAV';
update content_bodies set title = '【NIIGATA-SORADORI】黄金の渓谷　色鮮やかな紅葉　奥胎内　胎内市', description = '飯豊連峰の登山口に位置し、磐梯朝日国立公園に指定されている渓谷。ロイヤル胎内パークホテルから奥胎内ヒュッテまでの道のりは色鮮やかな紅葉が続き、紅葉狩りが楽しめる。' where id = 'FR7gLER4fAWLD4wXQ6LJs';
