update content_bodies set title = '十日町観光-新潟ふしぎさんがYukiMo!（快速便バス）で清津峡へ！', description = 'YukiMo!は、人気スポット清津峡から十日町市街や湯沢駅を結ぶ快速便バスです。今回はインスタグラマーの「新潟ふしぎさん」にYukiMo!で大地の芸術祭を鑑賞いただきました！清津峡を楽しみながら、十日町の伝統文化や温泉地にも手軽にアクセスできるYukiMo!で、地域の魅力を存分に味わう旅を体験してください！

