update content_bodies set title = '大糸線で行く　秘境を巡る鉄道旅-新潟ふしぎさんとのんびり糸魚川観光へ-', description = '"新潟県の糸魚川市から、長野県の松本市を結ぶローカル鉄道「大糸線」。今回はインスタグラマーの「新潟ふしぎさん」が大糸線に乗車し、沿線の観光を楽しんでいただきました！姫川沿いを走る絶景と、糸魚川の大自然や文化を満喫するひととき…大糸線での鉄道旅で、身も心もリフレッシュ！
