update content_bodies set title = 'A Railway Journey through Hidden Realms on the Oito Line - A Relaxing Tour of Itoigawa with Niigata Fushigi-san -', description = '"The Oito Line, a local railway connecting Itoigawa City in Niigata Prefecture to Matsumoto City in Nagano Prefecture. This time, Instagrammer ''Niigata Fushigi-san'' boarded the Oito Line and enjoyed sightseeing along the route! A moment to savor the breathtaking views along the Himekawa River and the great nature and culture of Itoigawa... Refresh your body and mind with a railway journey on the Oito Line! More details about the Oito Line here: ↓ https://oito-line-train.jp/"' where id = 'wcVCfpEdzjUqFgbIqqq5J';
update content_bodies set title = '祝 佐渡金山世界遺産登録！「黄金KAIDO」でお得な旅を／佐渡・新潟', description = '【黄金KAIDOとは……】
徳川直轄の金山であった「佐渡金山」（新潟県）と「土肥金山」（静岡県）は、家康公が開発に注力した金山であり、発掘された金は、江戸や大御所となった家康公が過ごした駿府に運ばれておりました。
長野県、山梨県にも金山があったことから、佐渡～土肥を結ぶ金を運んだ道を「黄金KAIDO」と命名いたしました。

【お得なドライブプラン】
黄金KAIDOエリアの高速道路がお得になるドライブプランを販売中

 【詳しくは公式webをチェック】
https://gold-road.jp/' where id = 'l2hdkmk4s5kRy3dxHQnBM';
update content_bodies set title = 'Celebrate the Registration of Sado Mine as a World Heritage Site! Enjoy a Great Trip on the ''Golden KAIDO'' / Sado, Niigata', description = '[What is Golden KAIDO...]
The ''Sado Mine'' (Niigata Prefecture) and ''Doi Mine'' (Shizuoka Prefecture) were gold mines directly controlled by Tokugawa, and they were the mines that Tokugawa Ieyasu focused on developing. The gold that was excavated was transported to Edo and to Sunpu, where Ieyasu spent his time as a shogun.
Since there were also gold mines in Nagano and Yamanashi Prefectures, we named the road that transported gold connecting Sado and Doi as ''Golden KAIDO''.

[Great Driving Plan]
We are currently offering a driving plan that makes the highways in the Golden KAIDO area more affordable.

[For more details, check the official website]
https://gold-road.jp/' where id = '4lTepCYUKfldxK-57CgET';
