update content_bodies set title = '【NIIGATA-SORADORI】清津峡　七色に染まる秘境　十日町市', description = 'にいがた観光ナビ【NIIGATA-SORADORI】
十日町市　清津峡　七色に染まる秘境

　新潟県十日町市にある日本三大渓谷のひとつ。その荘厳なる閃緑ひん岩と柱状節理の美しさをいっそう際立たせる紅葉シーズンには多くの観光客が訪れる。昭和６３年の落石事故により閉鎖されていたが、「清津峡渓谷トンネル」の開通により、今では安全に安心して堪能することができるようになった。絶景と同時に、温泉も満喫できる観光スポットでもある。

