update content_bodies set title = '[NIIGATA-SORADORI] Kiyotsu Gorge - A Hidden Paradise Drenched in Seven Colors, Tokamachi City', description = 'Niigata Tourism Navigation [NIIGATA-SORADORI]
Tokamachi City, Kiyotsu Gorge - A Hidden Paradise Drenched in Seven Colors

One of Japan''s three great gorges located in Tokamachi City, Niigata Prefecture. During the autumn foliage season, many tourists visit to witness the majestic beauty of the green schist and columnar jointing, which is further enhanced by the vibrant colors of the leaves. After being closed due to a rockfall accident in 1988, it is now safely accessible thanks to the opening of the ''Kiyotsu Gorge Tunnel.'' It is a tourist spot where you can enjoy breathtaking views as well as hot springs.

Public Interest Incorporated Association Niigata Prefecture Tourism Association
4-1 Shinko-cho, Chuo-ku, Niigata City, Niigata Prefecture 950-8570
Phone: 025-283-1188
Fax: 025-283-4345
http://www.niigata-kankou.or.jp' where id = 'xj3HtaB30MK0twG1kVCmo';
update content_bodies set title = '【新潟旅行】山頂が見ごろ！苗場ドラゴンドラ/田代ロープウェイ/湯沢町/新潟観光', description = '2022年10月の紅葉の様子です。山頂が見ごろを迎え、麓は色づき始めています。
苗場高原から田代高原をつなぐ“苗場ドラゴンドラ”で美しい紅葉と、雄大な“平標山”やエメラルドグリーンの神秘的な“二居湖”を眺めてみませんか？約5.5kmの空中散歩をぜひお楽しみください。土日は混雑するので平日がおすすめです。

運行期間：2022年10月8日（土）～11月6日（日）
____________________________________________

【基本情報】
https://niigata-kankou.or.jp/spot/10668

____________________________________________' where id = 'uA-ROJLOIw8NqWh6mjmZh';
update content_bodies set title = '[Niigata Trip] The Summit is at its Best! Naeba Dragondola / Tashiro Ropeway / Yuzawa Town / Niigata Tourism', description = 'This is the autumn foliage in October 2022. The summit is at its peak, and the base is starting to change colors.
Would you like to enjoy the beautiful autumn leaves from the ''Naeba Dragondola'' that connects Naeba Kogen and Tashiro Kogen, while taking in the majestic ''Hirakubo Mountain'' and the emerald green mystical ''Nii Lake''? Please enjoy the approximately 5.5 km aerial walk. Weekdays are recommended as weekends can be crowded.

Operating Period: October 8, 2022 (Saturday) to November 6, 2022 (Sunday)
____________________________________________

[Basic Information]
https://niigata-kankou.or.jp/spot/10668

____________________________________________' where id = 'SwkdkwK1CNW4CUfZP6hRb';
update content_bodies set title = '事実、想像を超える温泉地、新潟県。', description = 'ご存じでしょうか。
新潟県には、144もの温泉地があり、その数は実に全国3位であることを。

眼下に広がる雲海、湯けむり越しに望む日本海の夕日、日本有数の星空、
新潟の温泉は、実に多種多彩な魅力を持っています。

これから訪れるどんな人にとっても、
きっと“想像を超える”体験を与えてくれるはずです。' where id = 'llO4Dm-mJEngRcTwKHUEH';
update content_bodies set title = 'A hot spring destination that exceeds imagination, Niigata Prefecture.', description = 'Did you know?
Niigata Prefecture has 144 hot spring areas, ranking third in the country.

The sea of clouds spread out below, the sunset over the Japan Sea seen through the steam, one of Japan''s finest starry skies,
Niigata''s hot springs truly have a diverse range of attractions.

For anyone who visits from now on,
it is sure to provide an experience that will ''exceed imagination.''' where id = 'Hpo36l8S6GaB-iGZb2Zmg';
update content_bodies set title = '【石切参道商店街 観光PR動画】長編ver', description = '石切参道商店街は、歴史と活気に溢れた東大阪市随一の観光スポットです。
石切劔箭神社の門前町として古くから栄える商店街で、その風情と伝統的な雰囲気が心地よく広がる場所です。
お食事、お買い物などぜひお楽しみください！

チャンネル登録をよろしくお願いいたします！

ーーーーーーーーーーーーーーーーーーーーーーーーーー
【アクセス】
▼電車をご利用の方
近鉄奈良線 石切駅より 徒歩5分
近鉄けいはんな線 新石切駅より 徒歩10分

▼自動車をご利用の方
阪神高速 水走出口より 約5分
第二阪奈道路 西石切ランプ出口より 約5分
ーーーーーーーーーーーーーーーーーーーーーーーーーー

この動画は大阪府商店街店舗魅力向上支援事業を活用して作成しました。

#石切参道商店街 #石切劔箭神社 #東大阪' where id = 'aJ5TIeHl1iRIQm5yvs_bE';
update content_bodies set title = '[Ishikiri Sando Shopping Street Tourism PR Video] Long Version', description = 'Ishikiri Sando Shopping Street is the most prominent tourist spot in Higashi-Osaka City, filled with history and vibrancy.
It has flourished as a merchant town in front of Ishikiri Tsurugi Shrine, where its charm and traditional atmosphere spread comfortably.
Please enjoy dining, shopping, and more!

We appreciate your subscription to our channel!

ーーーーーーーーーーーーーーーーーーーーーーーーーー
[Access]
▼For those using the train
5 minutes on foot from Kintetsu Nara Line Ishikiri Station
10 minutes on foot from Kintetsu Keihanna Line Shin-Ishikiri Station

▼For those using a car
About 5 minutes from Hanshin Expressway Mizuhashi Exit
About 5 minutes from Daini Hannan Road Nishi-Ishikiri Ramp Exit
ーーーーーーーーーーーーーーーーーーーーーーーーーー

This video was created using the Osaka Prefecture Shopping Street Store Attraction Enhancement Support Project.

#IshikiriSandoShoppingStreet #IshikiriTsurugiShrine #HigashiOsaka' where id = '6FvfzlS7fjyt2gBhoa2wE';
update content_bodies set title = '村上・新発田エリアの郷土料理に満たされる旅へ ～新潟ローカルガストロノミー～', description = '村上・新発田エリアの生活文化を肌で感じ、郷土料理を満喫することのできるスポットを集めたコースです。
千年の月日を経て育まれた鮭文化を体感できる街並みや、美しい木彫堆朱の漆器、木樽を使った香り高い手作り味噌などからはどこか懐かしさを感じ、その土地の歴史や暮らしに想いを馳せることができます。
村上・新発田の郷土料理で満たされる旅を、ぜひご堪能ください。

【モデルコースはこちら】
https://niigata-kankou.or.jp/course/44726' where id = 'QZAhSXQ0KuG2Dq7g7Nssv';
update content_bodies set title = 'A Journey Filled with Local Cuisine of the Murakami and Shibata Area - Niigata Local Gastronomy -', description = 'This course gathers spots where you can experience the living culture of the Murakami and Shibata area and enjoy local cuisine.
The streets where you can experience the salmon culture nurtured over a thousand years, beautiful wood-carved lacquerware, and fragrant handmade miso made with wooden barrels evoke a sense of nostalgia, allowing you to reflect on the history and lifestyle of the region.
Please enjoy a journey filled with the local cuisine of Murakami and Shibata.

【Model course here】
https://niigata-kankou.or.jp/course/44726' where id = 'l9TPshsGcxtTypwVA3l90';
