update content_bodies set title = 'Digital Experience Guide(English)-The Revival of Tsuyama Castle-', description = '津山城天守閣などの高精細3DCG(3次元コンピューターグラフィックス)による再現、５カ国語(日本語・英語・中国語・韓国語・仏語)による文化財の歴史解説を行う4K動画。
津山市内3カ所に設置している、55インチのタッチパネルによるデジタルサイネージでも見ることができます。
【設置場所】
・箕作阮甫旧宅(岡山県津山市西新町6)
・備中櫓(津山城(鶴山公園)内:岡山県津山市山下)
・作州民芸館(岡山県津山市西今町18)

津山まちじゅう博物館ホームページ
https://tsuyama-machijuu.jp/guide/
#DigitalExperienceGuide #TsuyamaCastle #English' where id = 'zUit1RGr29VJhSxOThvRj';
update content_bodies set title = 'Digital Experience Guide(English)-The Revival of Tsuyama Castle-', description = 'A 4K video featuring high-resolution 3DCG (three-dimensional computer graphics) recreations of Tsuyama Castle''s main keep and historical explanations of cultural properties in five languages (Japanese, English, Chinese, Korean, and French).
It can also be viewed on 55-inch touch panel digital signage installed at three locations in Tsuyama City.
【Installation Locations】
・Former residence of Mitsukuri Genpo (6 Nishishinmachi, Tsuyama City, Okayama Prefecture)
・Bichu Yagura (within Tsuyama Castle (Tsuru Mountain Park): Yamashita, Tsuyama City, Okayama Prefecture)
・Sakushu Folk Art Museum (18 Nishiimacho, Tsuyama City, Okayama Prefecture)

Tsuyama City Museum website
