update content_bodies set title = '岡山県津山市観光PR動画', description = '岡山県津山市は岡山県の北部に位置し、北は鳥取県と接しています。

津山までは、岡山駅からJRで約１時間程度、岡山桃太郎空港からレンタカー、乗合タクシー等で約１時間程度、大阪市内から車で約２時間程度でアクセスできます。

【岡山県津山市の観光情報について】
https://www.tsuyamakan.jp

#岡山県観光
#津山市観光
#Okayama　Tourism　Promotion　Video' where id = 'MRLOhhgqwh-IrJbKfeNob';
update content_bodies set title = 'Tsuyama City, Okayama Prefecture Tourism PR Video', description = 'Tsuyama City is located in the northern part of Okayama Prefecture, bordering Tottori Prefecture to the north.

Tsuyama can be accessed by JR from Okayama Station in about one hour, by rental car or shared taxi from Okayama Momotaro Airport in about one hour, and by car from Osaka City in about two hours.

[Tourism Information about Tsuyama City, Okayama Prefecture]
https://www.tsuyamakan.jp

#Okayama Prefecture Tourism
#Tsuyama City Tourism
