update content_bodies set title = '【公式】トーベ・ヤンソンあけぼの子どもの森公園ライトアップ', description = 'トーベ・ヤンソンあけぼの子どもの森公園では、―森のすみかに灯るあかり「豊かな闇」を感じる時間―をコンセプトにライトアップを実施しています。土・日・祝日の日没～21：00までの限られた時間ですが、くつろいだり、カメラを持って訪れたり、北欧童話の幻想的な世界に入り込んでみてください。' where id = 'Y8HzAMLyWojwjSFsPgj9C';
update content_bodies set title = '[Official] Tove Jansson Akebono Children''s Forest Park Light Up', description = 'At Tove Jansson Akebono Children''s Forest Park, we are implementing a light-up event based on the concept of experiencing the time of ''rich darkness'' illuminated by lights in the forest''s dwelling. Although it is limited to a specific time from sunset to 21:00 on Saturdays, Sundays, and holidays, feel free to relax, bring your camera, and immerse yourself in the enchanting world of Nordic fairy tales.' where id = 'pXjgahY5f7GMrMqrGoGu-';
update content_bodies set title = '映画『urar suye』本編', description = '北海道・阿寒湖アイヌコタンを舞台に、現代に息づくアイヌの世界観を体感する短編映画『urar suye（ウララ スエ）』を公開

【ストーリー】
東京で音楽活動をしているユカリ（xiangyu）は、自分のアーティストとしての将来性を信じきれず、思い悩んでいた。そんな中、ユカリは大学の同級生であるダンサーのサヤに誘われ、釧路にある阿寒湖アイヌコタン（「コタン」は、アイヌ語で「集落」）を訪れることに。

アイヌコタンは〈創り作り手の街〉とも呼ばれており、人々の暮らしの中に伝統的に受け継がれた木彫りや刺繍、歌や踊りが息づいている。さらに、アイヌの世界観では、山や川、動物、樹木といった自然物や、火や雷などの自然現象、道具などに「カムイ」が宿ると信じられていた。
ユカリはアイヌコタンを巡りながら、人々が日々の営みの中でカムイの存在を全身で感じることで、自分自身と世界とのつながりを捉えなおしていく。

【冬編 cupki mawe はこちら】
https://youtu.be/SC5n7nuqLKk?si=fvN1rlarCZvvTT4w

