【Related Event】
A special screening of ''urar suye'' will be held at the opening event of ''Akan Ainu Art Week 2024.''
The opening event of ''Akan Ainu Art Week 2024,'' held at the Ainu Cultural Tradition and Creation Hall ''Onnechise'' on November 23, 2024, will feature a screening of this work as part of the program. For more details about the Akan Ainu Art Week, please visit the website.
