update content_bodies set title = 'SIRI WINTER', description = '阿寒湖の冬を楽しむ、アドベンチャー

ようこそ、ビギナーからエキスパートまで、誰もが楽しめる懐の深いフィールドへ。
この地を形づくった火山活動から奥深い森の豊かさまで、大地の鼓動を感じられる場所へと
アクセス良く出かけられるのが阿寒カルデラ アドベンチャーの最大の魅力。
世界レベル、第一級のフィールドがすぐそこに。
原始の面影を残す表情豊かな地形、多様性に富んだ動植物との出会いを求めて
感動と発見にあふれる冒険へ出かけよう。' where id = '4DXaa1Ee9lQ2xl0oZF5f3';
update content_bodies set title = 'SIRI WINTER', description = 'An adventure to enjoy the winter of Lake Akan

Welcome to a deep field where everyone from beginners to experts can enjoy.
The greatest charm of Akan Caldera Adventure is the easy access to a place where you can feel the heartbeat of the earth, from the volcanic activity that shaped this land to the richness of the deep forests.
World-class, first-rate fields are right there.
Let’s embark on an adventure filled with excitement and discovery, seeking encounters with diverse flora and fauna in a landscape that retains the traces of the primordial.' where id = 'P0CBGgIx8aExM-Pz6VC0h';
update content_bodies set title = '（公式）トーベ・ヤンソンあけぼの子どもの森公園', description = '平成9年の開園から20年を過ぎてもなお、たくさんの人に世代を超えて愛される、トーベ・ヤンソンあけぼの子どもの森公園。この公園は、北欧の童話作家として有名なトーベ・ヤンソンとの手紙のやり取りから生まれました。
　トーベ・ヤンソンの想いは、公園内のいろいろな処にちりばめられています。子どもも、大人も、生き物も、草花も。それぞれがお互いを受け入れ、自由に時間を過ごす。そんな空間が、トーベ・ヤンソンあけぼの子どもの森公園です。' where id = 'UEsZRA4QA7rhYhR77aYNA';
update content_bodies set title = '(Official) Tove Jansson Akebono Children''s Forest Park', description = 'Since its opening in 1997, Tove Jansson Akebono Children''s Forest Park has been loved by many people across generations, even after more than 20 years. This park was born from the correspondence with Tove Jansson, who is famous as a Nordic fairy tale writer.
Tove Jansson''s thoughts are scattered throughout various places in the park. Children, adults, living creatures, and plants all coexist. Each accepts one another and spends time freely. This is the space of Tove Jansson Akebono Children''s Forest Park.' where id = 'MzSaN7rB3rDA6Pkv5LJEv';
update content_bodies set title = '寄居北條まつり 2018 【4K ドローン空撮】', description = '寄居北條まつり (2018)

戦国時代に行われた、北条軍と豊臣軍による合戦を再現する祭り。日本 100 名城の一つ「鉢形城」を背に、大砲のごう音が鳴り響く中行われる。刀や槍での戦いは、まるで戦国時代へとタイムスリップしたかのような迫力です。' where id = 'U5dZ6DSv4PC2cQOqaSVlB';
update content_bodies set title = 'Yorii Hojo Festival 2018 【4K Drone Footage】', description = 'Yorii Hojo Festival (2018)

