update content_bodies set title = 'なんとの宿　～たびたび訪れたい、懐かしい場所～　（南砺の宿プロモーション映像／南砺市観光協会）', description = '南砺の宿　～たびたび訪れたい、懐かしい場所～　【ダイジェスト版】

なんと安全・安心と笑顔の宿キャンペーン【第二弾】の実施に合わせて、南砺市内の宿泊施設の魅力を伝えるプロモーション映像を制作しました。南砺の土地の恵みと南砺に住む人々の温かい心に触れ、心も身体もリフレッシュする旅をご提案します。

《映像テーマ》
女性２人が大人女子旅に出掛けて南砺を訪れる。食事・温泉・交流・建物の４つのテーマを通して南砺の土地の恵みとそこに住む人々の温かい心に触れていく。旅先という非日常の中にも、その土地に住む人の日常が溢れていることに気づき、「日常の大切さ」を再認識する。大人女子旅に出掛けている妻とその間家で留守番をしている夫の対比で面白く描いている。

