update content_bodies set title = '「神奈川ルルルン♪」 - 足柄エリアでアクティブに', description = '「神奈川ルルルン♪」は、あなたに神奈川を旅する最高の方法を示します。心を揺さぶる体験が満載で、思わず「ルルルン」と口ずさみたくなることでしょう！

[足柄エリア]
足柄エリアの絶景スポットを駆け抜けているような気分になれます。富士山のパノラマビューを提供する足柄峠や、「金太郎」の物語で有名な金時山などがあります。足柄の大自然の中で心と体を開放しましょう。

・パルカブ
・大雄山最乗寺
・松田山でのミカン狩り
・松田桜まつり/菜の花まつり
・夕日の滝
・瀬戸酒造
・金時山

