update content_bodies set title = '[Minamiashigara City] Early Blooming Cherry Blossom ''Harumeki''', description = 'Introducing ''Harumeki'' (cherry blossom) that reaches its peak in Minamiashigara City, Kanagawa Prefecture.
Harumeki is an early blooming cherry blossom that reaches its peak in mid-March. The video features cherry blossoms blooming at ''Ichinoseki Harane'' and ''Haruki Path / Happiness Path''.

Access
■ Public Transportation
・ ''Ichinoseki Harane''
15 minutes on foot from ''Ashigara High School Mae'' bus stop, which can be reached by Hakone Tozan Bus from Odakyu Line Shin-Matsuda Station or JR Line Matsuda Station.
15 minutes on foot from ''Ashigara High School Mae'' bus stop, which can be reached by Hakone Tozan Bus from Daiyuzan Line Daiyuzan Station to Shin-Matsuda Station.
・ ''Haruki Path / Happiness Path''
5 minutes on foot from Fuji Film Mae Station on the Daiyuzan Line.
