update content_bodies set title = '小田原・箱根の木象嵌　2018/1/12 Fri', description = '象嵌とは、象り（かたどり）、嵌める（はめる）という意味の工芸技法。木象嵌は、様々な種類の天然の樹木の色や木目を活かし、組み合わせて描き出される木画です。
国内で木象嵌の産地を形成しているのは、唯一、小田原・箱根地域だけです。

この動画では、小田原・箱根地域特有の糸鋸ミシンを用いた挽き抜き象嵌技法を紹介しています。

出演：
