update content_bodies set title = 'Wood Inlay of Odawara and Hakone 2018/1/12 Fri', description = 'Inlay refers to a craft technique that means to shape (kata-dori) and to fit (hame-ru). Wood inlay is a wooden painting created by utilizing and combining the colors and grains of various types of natural trees.
The only region in Japan that forms a production area for wood inlay is the Odawara and Hakone area.

This video introduces the inlay technique using a unique scroll saw sewing machine specific to the Odawara and Hakone region.

Featuring:
Tadao Takahashi (Wood Inlay Artist / Representative of Wood Inlay Workshop Sada)
http://mokuzougan.blog14.fc2.com/

Cooperation:
Hakone Product Association
http://www.hakonebussan.com/

