update content_bodies set title = 'GREENable HIRUZEN', description = 'いつからか人々の生活が自然の営みから距離を置いたことで人と自然の均衡が崩れつつある中、人と自然が共に育む生態系が蒜山にはまだ残っている。そこは、人と自然が不可分に溶け合い、『蒜山時間』とも言われる、自然の流れに合わせゆったりとした時間が流れる空間。人と自然が互いに活かし生きるために、自然を守り、豊かに育てる。GREENableは、人と自然が共に生きられる関係性を回復する活動でありブランド。
私たちが本当に持っていた豊かさをここ蒜山で感じてみませんか。

GREENable HIRUZEN
 HP : https://greenable-hiruzen.co.jp/
 Instagram :  https://www.instagram.com/greenable_hrzn/


#GREENable #GREENableHIRUZEN #自然とつながる出発点 #蒜山 #sustainablejourney' where id = 'n6xVqAEbqpFzSLUdEd3le';
update content_bodies set title = 'GREENable HIRUZEN', description = 'As people have distanced their lives from the rhythms of nature, the balance between humans and nature is gradually breaking down. However, in Hiruzan, an ecosystem where humans and nature nurture each other still remains. It is a space where humans and nature are inseparably intertwined, flowing in harmony with nature''s rhythm, often referred to as ''Hiruzan time.'' To live in a way that benefits both humans and nature, we protect and enrich the natural environment. GREENable is an initiative and brand that aims to restore the relationship where humans and nature can coexist. 

Why not experience the true richness we once had here in Hiruzan?

GREENable HIRUZEN
 HP : https://greenable-hiruzen.co.jp/
 Instagram : https://www.instagram.com/greenable_hrzn/

#GREENable #GREENableHIRUZEN #StartingPointToConnectWithNature #Hiruzan #sustainablejourney' where id = 'I0BTJ_mS8avbVdl-LnEf4';
update content_bodies set title = '瀬見温泉', description = '最上小国川の清流に臨む静かな温泉場。山水の景勝に恵まれ、特に紅葉の季節がすばらしい温泉地です。源義経の妻、北の方が亀若丸を生んだ際、産湯を探しに出た弁慶が近くの岩陰から立ち昇る湯煙を見つけたのがこの温泉の始まりと伝えられています。近くには亀若丸の誕生に加護のあった亀割子安観音や瀬見温泉の守り神が祀られている湯前神社など、義経・弁慶に関する伝説や旧跡が数多く残っています。夏は、近くを流れる最上小国川でアユ釣りを楽しむ方を多く見かけます' where id = 'qiBH-C6Kw9u2XHBiM9zs2';
update content_bodies set title = 'Semmi Onsen', description = 'A quiet hot spring resort overlooking the clear stream of the Mogami Oguni River. Blessed with scenic mountain waters, this hot spring area is particularly wonderful during the autumn foliage season. It is said that the origin of this hot spring began when Benkei, searching for a birthing bath for his wife, the noblewoman Kito, who gave birth to Kamewakamaru, discovered the rising steam from a nearby rock. Nearby, there are many legends and historical sites related to Yoshitsune and Benkei, such as the Kamewakamaru''s protective Kamewariko An Kannon and the Yumemae Shrine, which enshrines the guardian deity of Semmi Onsen. In summer, many people can be seen enjoying sweetfish fishing in the nearby Mogami Oguni River.' where id = '_g4VuP1EgmRcsUr2xwpBC';
update content_bodies set title = '山刀伐峠', description = '山刀伐峠は、最上町と尾花沢市を結ぶ峠のひとつで、標高は470メートルにすぎませんが、北の最上町側は急峻で、南の尾花沢市側は比較的なだらかな地形をしています。元禄2年(1689)5月17日、陽暦にすると7月3日。松尾芭蕉と河合曾良は最上町の封人の家に逗留した後、「おくのほそ道」でも“最大の難所”と言われている山刀伐峠を越えて、尾花沢市へ向かいました。現在は散策道として整備され、300年の時を越えても尚、松尾芭蕉の旅を偲ぶ貴重な史跡となっています。' where id = 'XdmCd-8QZ9jq7AepZS558';
update content_bodies set title = 'Yamato-bari Pass', description = 'Yamato-bari Pass is one of the mountain passes connecting Mogami Town and Obanazawa City. Although its elevation is only 470 meters, the northern side towards Mogami Town is steep, while the southern side towards Obanazawa City has a relatively gentle terrain. On May 17, 1689, in the Gregorian calendar, July 3, Matsuo Basho and Kawai Sora stayed at the house of a feudal lord in Mogami Town before crossing the Yamato-bari Pass, which is said to be the ''most difficult point'' in ''The Narrow Road to the Deep North,'' and headed towards Obanazawa City. Today, it has been developed as a walking path and remains a valuable historical site that evokes the journey of Matsuo Basho even after 300 years.' where id = 'QmXIDYun7C9iEgmy2PJxw';
update content_bodies set title = '堺田分水嶺', description = '陸羽東線の堺田駅前には、太平洋と日本海へと水が分かれる分水嶺があります。一般的な分水嶺は、山脈や丘陵地などの高い地形に形成されますが、平坦な場所にあるのは珍しく、その流れを見ることができます。' where id = 'l4vyEabsjXTjHGDx00llo';
update content_bodies set title = 'Sakaida Watershed', description = 'In front of Sakaida Station on the Rikuuhigashi Line, there is a watershed where water divides into the Pacific Ocean and the Japan Sea. 
Typically, watersheds are formed in high terrains such as mountain ranges or hills, but it is rare to find one in a flat area where you can see the flow.' where id = 'vZ1IP0QefG8Rt8C1dshx-';
update content_bodies set title = '【東北・山形】「EMMA」山形県最上町プロモーション動画  Promotion Video for Mogami Town, Yamagata (Tohoku, Japan)', description = '[山形県最上町の歴史や風景を背景にした心が動かされる短編物語]

　最上町は、古来より馬の産地であり、小国駒と呼ばれる名馬の産地として、馬を慈しみ深い関わりを持って暮らしてきた町であった。
　今回のプロモーション動画は、東北三大馬頭観音の一つであり、馬の守り神として崇拝されてきた富山馬頭観音の東善院と、近代では観光地として「馬」に関わりの深い前森高原をメインロケ地にし、その2箇所が『桜』の名所でもあり、『馬』と『桜』、その桜のイメージから『女性』をテーマに、主人公の過去から未来に繋がるストーリーを町の魅力的なロケ地を活かして制作。


[A moving short story set against the backdrop of the history and scenery of Mogami Town, Yamagata Prefecture]

Mogami Town has been a horse-breeding town since ancient times, and as the birthplace of the famous horse called Oguni Koma, it has been a town where people have lived in a beautiful and deep connection with horses.
The main locations for this promotional video are Tozen-in Temple of Tomiyama Bato Kannon, one of the three major horse-headed Kannon temples in the Tohoku region and worshipped as the guardian deity of horses, and Maemori Plateau, which has a deep connection with horses as a tourist destination in modern times. These two places are also famous for cherry blossoms. The story is based on the theme of horses, cherry blossoms, and the protagonist, taking advantage of the town''s attractive locations to create a story that connects the protagonist''s pas, present, and future.


***

