update content_bodies set title = 'The SUKIYAKI Gastronomy Cyclingｰtour', description = '■Activity details■
With its waterways, traditional old houses, and beautiful rural villages, Niu is the perfect place to enjoy a cycling adventure through unique Japanese scenery. The locals are proud of their pioneering spirit and still talk about the days long ago when people dug waterways through the barren land, making it into a lush agricultural community. This program offers participants the chance to cycle amongst the seasonal scenery of the village while experiencing its history. After the bike ride, they''ll enjoy sukiyaki made with Special Matsusaka Beef. Matsusaka Beef is already world famous, but this variety accounts for a mere 4% of all Matsusaka cows, making it a particularly special treat. This is a luxurious cycling tour through gorgeous villages followed by the ultimate Wagyu beef.
An optional organic farm vegetable picking activity is also available.

■コンテンツの概要＆ストーリー■
日本の原風景をサイクリングで走り抜ける。そんな場所にぴったりなのが、水路や古民家等、美しい里山の風景が広がる丹生。ここはかつて、痩せた土地を人々の手で水路を引き、豊かな農村したというストーリーがあり、今もこの土地の人々の誇りとして語り継がれています。本プログラムでは、このエリアの歴史に触れながら、四季折々の里山のサイクリングを楽しめます。サイクリングの後は、世界的に有名な松阪牛のなかでも、たった4%しか存在しない幻の「特産松阪牛」のすきやきに舌鼓。里山の美しい風景と最高級和牛をまるごと味わえる、贅沢なサイクリングツアーです
※オプションでオーガニック農園での収穫体験もございます。

■特設サイト”Exclusive Activities Information for Travel Agencies”　
＊日本語：https://www.kankomie.or.jp/special/fortravelagencies/
＊English：https://www.kankomie.or.jp/special/fortravelagencies/en/

三重県の豊かな自然の恵みや人々の生活に触れ、「三重県ならでは」の魅力を存分に感じることができる、特別な体験をご用意しました。ぜひ上記サイトより詳細をご確認ください。
We’d like to offer you exclusive experiences that will allow you to experience the rich natural bounty of Mie Prefecture and the lives of its people, and to fully appreciate the charms "unique to Mie Prefecture".
Please check the website link above for more information.' where id = '64u-HpsFgDord0cDphhGn';
update content_bodies set title = 'The SUKIYAKI Gastronomy Cycling-tour', description = '■Activity details■
With its waterways, traditional old houses, and beautiful rural villages, Niu is the perfect place to enjoy a cycling adventure through unique Japanese scenery. The locals are proud of their pioneering spirit and still talk about the days long ago when people dug waterways through the barren land, making it into a lush agricultural community. This program offers participants the chance to cycle amongst the seasonal scenery of the village while experiencing its history. After the bike ride, they''ll enjoy sukiyaki made with Special Matsusaka Beef. Matsusaka Beef is already world famous, but this variety accounts for a mere 4% of all Matsusaka cows, making it a particularly special treat. This is a luxurious cycling tour through gorgeous villages followed by the ultimate Wagyu beef.
An optional organic farm vegetable picking activity is also available.

■Overview & Story of the Content■
Cycling through the original landscapes of Japan. Niu, with its waterways and traditional old houses, is the perfect place for such an experience, showcasing the beautiful rural scenery. There is a story here of how people once dug waterways through barren land, transforming it into a rich agricultural community, a tale that is still passed down as a source of pride for the locals. This program allows participants to enjoy cycling through the seasonal scenery of the rural area while touching upon its history. After cycling, participants will savor sukiyaki made from the rare "Special Matsusaka Beef," which accounts for only 4% of all Matsusaka beef, a truly luxurious treat. This is a lavish cycling tour that allows you to fully enjoy the beautiful landscapes of the rural area and the finest Wagyu beef.
*An optional organic farm harvesting experience is also available.

■Special Site “Exclusive Activities Information for Travel Agencies”  
