update content_bodies set title = 'Walk the Magose pass on the Kumano Kodo trail, UNESCO World heritage site', description = '■Activity details■
Long ago, it was popular for people from all across Japan to walk hundreds of kilometers to tour sacred sites such as Ise Grand Shrine and Kumano Sanzan (the Three Grand Shrines of Kumano). Many travelers walked the perilous Magose Pass, which is part of the Sacred Sites and Pilgrimage Routes in the Kii Mountain Range that leads to Kumano Sanzan. The beautiful stone paved path leading deep into the forest has been lovingly maintained by locals for centuries, and still looks as it did long ago. This program offers participants the chance to dress in travel garb recreated from ukiyo-e prints and historic documents and walk the Magose Past just as ancient travelers did. Partial proceeds from the program are used to preserve the stone paving and keep the scenery in pristine condition for future generations.

■Overview & Story of the Content■
In the past, there was a great boom in Japan where people walked hundreds of kilometers from all over the country to visit sacred sites such as Ise Grand Shrine and Kumano Sanzan. The Magose Pass, which is part of the UNESCO World Heritage Site "Sacred Sites and Pilgrimage Routes in the Kii Mountain Range," is one of the "paths of prayer" that many travelers crossed to visit Kumano Sanzan. The beautiful stone-paved path extending deep into the forest has been carefully preserved by local people for hundreds of years and still retains its original appearance. In this program, participants will don travel garments recreated from ukiyo-e and historical documents and walk the Magose Pass just like the ancient travelers did. A portion of the experience fee will be used for the preservation of the stone pavement to ensure that this beautiful scenery remains for future generations.

■Special Site “Exclusive Activities Information for Travel Agencies”  
＊Japanese: https://www.kankomie.or.jp/special/fortravelagencies/  
＊English: https://www.kankomie.or.jp/special/fortravelagencies/en/

