update content_bodies set title = '京都一周トレイル　ダイジェスト', description = '京都の東南、伏見桃山から、比叡山、大原、鞍馬を経て、高雄、嵐山、苔寺に至る全長約83.3キロの４コース（東山、北山東、北山西、西山）と、豊かな森林や清流、田園風景に恵まれた京北地域をめぐる全長約48.7キロの１コースからなる「京都一周トレイル」の紹介動画ダイジェスト版です。
　京都の自然、世界遺産をはじめとする歴史・文化、グルメ情報などを紹介しています。

◆事業者の方へ
「京都一周トレイル」は京都一周トレイル会の登録商標です。
　御利用される前には公式サイトを確認のうえ、事前に御連絡をお願いします。
問合せ先：京都市産業観光局観光MICE推進室　京都一周トレイル担当宛
kanko-mice@city.kyoto.lg.jp

◆関連サイト
京都一周トレイル公式サイト
