update content_bodies set title = 'Kyoto Circular Trail Digest', description = 'This is a digest video introducing the "Kyoto Circular Trail," which consists of four courses (Higashiyama, Kitayama East, Kitayama West, and Nishiyama) totaling approximately 83.3 kilometers, starting from Fushimi Momoyama in the southeast of Kyoto, passing through Mount Hiei, Ohara, and Kurama, and reaching Takao, Arashiyama, and the Moss Temple, as well as one course of approximately 48.7 kilometers that explores the rich forests, clear streams, and rural landscapes of the Kyoko region.
It introduces Kyoto''s nature, historical and cultural heritage including World Heritage sites, and gourmet information.

◆ For Businesses
The "Kyoto Circular Trail" is a registered trademark of the Kyoto Circular Trail Association.
Please check the official website and contact us in advance before use.
Contact: Kyoto City Industrial Tourism Bureau, Tourism MICE Promotion Office, Kyoto Circular Trail Division
kanko-mice@city.kyoto.lg.jp

◆ Related Site
Kyoto Circular Trail Official Site
