update content_bodies set title = '【京都一周トレイル®公式】京北コース', description = '京都一周トレイル🄬「京北コース」は、京都駅からバスで1時間の自然豊かな京北地域を一周する約48.7kmのコース。
全域が丹波高原に含まれ、9割以上が森林地帯。夏でも涼しく、緑に恵まれた地域です。滝又の滝、桜で有名な常照皇寺、魚ヶ渕の吊橋など多くの名勝や、里山風景を一望できる絶景ポイントなど、見所あふれる散策が楽しめます。（他のコースより、やや上級者向けです。）

