update content_bodies set title = 'KYOTO SERENDIPITY - シャルロット・ペリアン', description = '「空間にリズムを与える、自由な形」。モダニズムのデザイナー、シャルロット・ペリアンが京都を訪れた際、彼女は変革的なインスピレーションを見出しました。桂離宮の棚は、彼女の有名な『Nuage a Plots』書棚に直接影響を与えました。

桂離宮から河井寛次郎との民藝哲学まで、京都は彼女にとってアイデアの交差点でした。20世紀を形作ったデザインのルーツを探求しましょう。人生のあらゆる瞬間における時を超えた美しさ。' where id = 'CybXi46ViSN7Q6iZY2J25';
update content_bodies set title = 'KYOTO SERENDIPITY - Charlotte Perriand', description = '"A free form that gives rhythm to space." When modernist designer Charlotte Perriand visited Kyoto, she found a transformative inspiration. The shelving at Katsura Imperial Villa directly inspired her famous "Nuage a Plots“ bookshelf
From the imperial villa to the philosophy of Mingei with Kanjiro Kawai, Kyoto was a meeting ground of ideas for her. Explore the roots of the design that shaped the 20th century. Timeless beauty in every moment of life.

「空間にリズムを与える、自由な形」。 モダニズムの巨匠シャルロット・ペリアン。彼女の代表作である『Nuage a Plots bookshelf』は、実は京都の桂離宮にある「違い棚」から着想を得て生まれたと言われています。
桂離宮の機能美、そして河井寛次郎らとの出会いによる民藝哲学への共感。 20世紀のデザイン史に影響を与えた、「出会い」の物語に触れよう。' where id = 'yXFXJzVxQpgreemp52bGA';
update content_bodies set title = '京都のセレンディピティ - ジョン・ケージ', description = '「静寂とは、音がないことではなく、心の扉を開くこと」。
伝説的な作曲家ジョン・ケージは、龍安寺の石庭で深い「音の風景」を発見しました。
彼は石をただ観察するだけでなく、その輪郭をなぞって音楽を作り出し、偶然性と虚無の中に美を見出しました。
彼にとって、京都の美意識は音楽そのものでした。
喧騒から離れ、自分自身の静寂を見つけてください。
人生のすべての瞬間に時を超えた美があります。' where id = 'hHHjtn9s0cg26vLxTJ_35';
update content_bodies set title = 'KYOTO SERENDIPITY - John Cage', description = '"Silence is not the absence of sound, but the opening of the mind." Legendary composer John Cage discovered a profound "Soundscape" in the rock garden of Ryoan-ji Temple. He didn''t just observe the stones; he traced their outlines to compose music, finding beauty in chance and emptiness.
For him, the aesthetics of Kyoto were like music itself. Step away from the noise and find your own silence. Timeless beauty in every moment of life.

「静寂とは、音がないことではなく、心の扉を開くこと」。 音楽家・ジョン・ケージは、龍安寺の石庭に深いインスピレーションを受けました。彼は石庭を眺めるだけではなく、石の輪郭をなぞることで音を紡ぎ、偶然性と虚無の中に音楽を見出したのです。
彼にとって、京都の美意識は音楽そのものでした。 日常の喧騒を離れ、心研ぎ澄ます静寂の旅へ。' where id = 'QUjA6m5m1eyDkP6Q-lmRI';
update content_bodies set title = '京都のセレンディピティ - イザベラ・バード', description = '「ガイドブックのその先にある、真の京都」。1878年、英国人探検家イザベラ・バードは京都で単なる風景以上のものを見つけました。彼女は人々の日常生活に織り込まれた「清潔さ」、「自尊心」、そして「相互扶助」を目にしました。
彼女の著書『日本の未踏の道』に記したように、「日本の人々はまじめで勤勉で礼儀正しい」。彼女が感動した普遍的な美徳を発見し、人生のあらゆる瞬間に見られる時を超えた美に触れる旅へ。' where id = 'aV7hv4OvNm5U6EGUtnYsk';
update content_bodies set title = 'KYOTO SERENDIPITY - Isabella Bird', description = '"Beyond the guidebooks, the true Kyoto awaits." In 1878, British explorer Isabella Bird found more than just scenery in Kyoto. She saw "immaculate cleanliness," "self-respect," and "shared responsibilities" woven into the everyday lives of the people.
As she noted in her book Unbeaten Tracks in Japan: "The Japanese are wonderfully gentle, courteous, and good-tempered." Discover the universal virtues she admired?a timeless beauty found in every moment of life.

「ガイドブックのその先にある、真の京都」。 明治期、1878年に京都を訪れた英国人探検家イザベラ・バード。彼女がこの地で見つけたのは、単なる風景ではなく、人々の暮らしに根付く「清潔さ」「自尊心」、そして「相互扶助」の精神でした。
「日本の人々はまじめで勤勉で礼儀正しい」。 彼女が感動した普遍的な美徳と、受け継がれる暮らしの美に触れる旅へ。' where id = 'MF3dNzsHJa3NMI-V357eS';
update content_bodies set title = 'カラフルカラツ　～ココロ、うごく、イロイロ～【唐津の海】', description = '季節や時間帯でその表情がカラフルに変化する唐津の海。
まだ見たことのない自然の色に触れることで、新しいイロイロを見つけることができるかもしれません。' where id = 'jL4DcS6YjjjCPeDI7ZBEr';
