update content_bodies set title = '[PV] Fresh Green Nishikawa Town', description = 'Nishikawa Town is located almost in the center of Yamagata Prefecture, spreading at the foot of the famous Mt. Gassan. 
Please enjoy the video that captures the beauty of fresh greenery surrounded by rich nature.' where id = '340Sp_HM2Eq31UU1LLOV0';
update content_bodies set title = '【サウナ月山】西川町の本気サウナで極上の"ととのい"体験はいかが？', description = '山形県西川町のサウナー町長が本気で作ったサウナをご紹介！

リニューアルオープンした水沢温泉館のサウナは、北欧フィンランドの伝統的なサウナを基本にしており、山形県内でも珍しいセルフロウリュを設置！
月山の雪解け水風呂でクールダウンした後は大自然で寝ころぶ外気浴で、最高の"ととのい"をお届けします✨

さらには『カリーショップくじら』プロデュースのサ飯で追い汗もばっちり💦

西川町・水沢温泉館で極上サウナ体験をしてみませんか？
 
#水沢温泉 #水沢温泉館 #山形県西川町 #西川町 #山形観光 #山形サウナ #サウナ #サウナ女子 #サ活 #サウナイキタイ #サウナ好きな人と繋がりたい #フィンランド式サウナ #セルフロウリュ #水風呂 #外気浴 #インフィニティチェア' where id = 'KEkiBzyEKhnOEGzg2_PdI';
update content_bodies set title = 'How about an exquisite ''totonoi'' experience at the serious sauna in Nishikawa Town, Mt. Yudono?', description = 'Introducing the sauna created with passion by the sauna-loving mayor of Nishikawa Town in Yamagata Prefecture!

The sauna at the newly renovated Mizusawa Onsenkan is based on the traditional Finnish sauna and features a rare self-rolling system in Yamagata Prefecture!
After cooling down in the snowmelt water bath of Mt. Yudono, enjoy the ultimate ''totonoi'' experience by relaxing in the great outdoors✨

Additionally, you can replenish your energy with the delicious meals produced by ''Curry Shop Kujira'' after sweating it out💦

Would you like to experience the ultimate sauna at Mizusawa Onsenkan in Nishikawa Town?

